import {b, type ReviewedLesson} from './types';

const lessons: Record<string, ReviewedLesson> = {
  'm2-w086-e1': {
    title:b('Ghost-sample Jensen step','Bước Jensen với mẫu ghost'),
    prompt:b(String.raw`Let $S=(Z_1,\ldots,Z_n)$ and let $S'$ be an independent IID ghost sample. For a measurable/separable class $\mathcal F$, prove $E\sup_f|P_nf-Pf|\le E\sup_f|P_nf-P'_nf|$.`,String.raw`Cho $S=(Z_1,\ldots,Z_n)$ và $S'$ là mẫu ghost IID độc lập. Với lớp đo được/tách được $\mathcal F$, hãy chứng minh $E\sup_f|P_nf-Pf|\le E\sup_f|P_nf-P'_nf|$.`),
    application:b('A second independent validation sample replaces an unknown population mean by a conditional expectation, creating the first symmetrization bound.','Mẫu kiểm định độc lập thứ hai thay trung bình tổng thể chưa biết bằng kỳ vọng có điều kiện, tạo cận symmetrization đầu tiên.'),
    formula:b(String.raw`With $P_nf=n^{-1}\sum_i f(Z_i)$ and $P'_nf=n^{-1}\sum_i f(Z'_i)$, $E\sup_{f\in\mathcal F}|P_nf-Pf|\le E\sup_{f\in\mathcal F}|P_nf-P'_nf|$, assuming the relevant suprema are measurable/separable.`,String.raw`Với $P_nf=n^{-1}\sum_i f(Z_i)$ và $P'_nf=n^{-1}\sum_i f(Z'_i)$, $E\sup_{f\in\mathcal F}|P_nf-Pf|\le E\sup_{f\in\mathcal F}|P_nf-P'_nf|$, giả sử các supremum liên quan đo được/tách được.`),
    steps:[b('Condition on the observed sample S and express Pf as the conditional mean of the ghost empirical average.','Điều kiện theo mẫu S đã quan sát và viết Pf thành trung bình có điều kiện của empirical average ghost.'),b(String.raw`Apply conditional Jensen to each $|P_nf-P'_nf|$ while keeping the same conditioning for the whole class.`,String.raw`Áp Jensen có điều kiện cho từng $|P_nf-P'_nf|$ với cùng điều kiện cho cả lớp.`),b('Use measurability/separability to pass to the supremum and then take expectation over S.','Dùng tính đo được/tách được để chuyển qua supremum rồi lấy kỳ vọng theo S.')],
    primarySolution:[b(String.raw`Given S, IID sampling of $S'$ gives $E[P'_nf\mid S]=Pf$ for each fixed f.`,String.raw`Cho S, tính IID của $S'$ cho $E[P'_nf\mid S]=Pf$ với từng f cố định.`),b(String.raw`Therefore $P_nf-Pf=E[P_nf-P'_nf\mid S]$. By conditional Jensen, $|P_nf-Pf|\le E[|P_nf-P'_nf|\mid S]$.`,String.raw`Do đó $P_nf-Pf=E[P_nf-P'_nf\mid S]$. Theo Jensen có điều kiện, $|P_nf-Pf|\le E[|P_nf-P'_nf|\mid S]$.`),b('The right side is bounded by the conditional expectation of the supremum over f. Under the stated separability/measurability assumption, take sup_f and then expectation to get the desired inequality.','Vế phải bị chặn bởi kỳ vọng có điều kiện của supremum theo f. Dưới giả thiết tách được/đo được đã nêu, lấy sup_f rồi kỳ vọng để được bất đẳng thức cần chứng minh.'),b('If the supremum is not measurable, the result must be stated with outer expectation or a measurable subclass; the exchange is not automatic.','Nếu supremum không đo được, cần phát biểu bằng outer expectation hoặc lớp con đo được; phép đổi thứ tự không tự động hợp lệ.')],
    companions:[
      {prompt:b(String.raw`Let $\mathcal F=\{f\}$ contain one bounded function and condition on a fixed sample S. Show the ghost-sample Jensen inequality for that single f.`,String.raw`Cho $\mathcal F=\{f\}$ chỉ có một hàm bị chặn và điều kiện theo mẫu S cố định. Hãy chứng minh bất đẳng thức Jensen với mẫu ghost cho f đó.`),solution:[b(String.raw`Independence gives $E[P'_nf\mid S]=Pf$.`,String.raw`Tính độc lập cho $E[P'_nf\mid S]=Pf$.`),b(String.raw`Thus $P_nf-Pf=E[P_nf-P'_nf\mid S]$.`,String.raw`Do đó $P_nf-Pf=E[P_nf-P'_nf\mid S]$.`),b(String.raw`Jensen for absolute value gives $|P_nf-Pf|\le E[|P_nf-P'_nf|\mid S]$; taking expectation over S proves the one-function case.`,String.raw`Jensen cho trị tuyệt đối cho $|P_nf-Pf|\le E[|P_nf-P'_nf|\mid S]$; lấy kỳ vọng theo S chứng minh trường hợp một hàm.`)]},
      {prompt:b(String.raw`For a finite class $\mathcal F=\{f_1,f_2\}$, explain the conditional supremum step that turns two Jensen bounds into a single bound on $\max_j|P_nf_j-Pf_j|$.`,String.raw`Với lớp hữu hạn $\mathcal F=\{f_1,f_2\}$, hãy giải thích bước supremum có điều kiện biến hai cận Jensen thành cận cho $\max_j|P_nf_j-Pf_j|$.`),solution:[b(String.raw`Apply conditional Jensen separately to $f_1$ and $f_2$.`,String.raw`Áp Jensen có điều kiện riêng cho $f_1$ và $f_2$.`),b(String.raw`Each right side is at most $E[\max_j|P_nf_j-P'_nf_j|\mid S]$, since the maximum dominates either term pointwise.`,String.raw`Mỗi vế phải không quá $E[\max_j|P_nf_j-P'_nf_j|\mid S]$, vì maximum lớn hơn từng hạng tại mọi điểm.`),b('Taking the maximum on the left and then expectation proves the finite-class inequality without any uncountable-class measurability issue.','Lấy maximum vế trái rồi kỳ vọng chứng minh bất đẳng thức lớp hữu hạn, không gặp vấn đề đo được của lớp không đếm được.') ]},
      {prompt:b(String.raw`Suppose $\mathcal F$ is uncountable and the pointwise Jensen argument is valid for every f. What extra issue remains before taking $E\sup_f$?`,String.raw`Giả sử $\mathcal F$ không đếm được và lập luận Jensen điểm đúng với mọi f. Còn vấn đề gì trước khi lấy $E\sup_f$?`),solution:[b('The pointwise inequalities alone do not guarantee that the supremum is a measurable random variable.','Các bất đẳng thức điểm riêng không bảo đảm supremum là biến ngẫu nhiên đo được.'),b('One needs a measurable/separable version of the class or must formulate the result with outer expectation.','Cần phiên bản lớp đo được/tách được hoặc phải phát biểu kết quả bằng outer expectation.'),b('Only after that justification may the supremum and expectation be interchanged in the symmetrization bound.','Chỉ sau biện minh đó mới được chuyển supremum và kỳ vọng trong cận symmetrization.') ]},
    ],
    reviewNote:'Checked the conditioning sigma-field, ghost-sample independence, Jensen direction and the exact measurability step; the uncountable-class case is qualified.',sourceIds:['o-cmu705'],
  },
  'm2-w086-e2': {
    title:b('Insert Rademacher signs by exchangeability','Chèn dấu Rademacher nhờ tính đổi chỗ'),
    prompt:b(String.raw`Starting from the ghost difference, prove $E\sup_f|P_nf-P'_nf|\le2E\sup_f|n^{-1}\sum_i\sigma_i f(Z_i)|$. State why the signs may be inserted.`,String.raw`Bắt đầu từ hiệu ghost, hãy chứng minh $E\sup_f|P_nf-P'_nf|\le2E\sup_f|n^{-1}\sum_i\sigma_i f(Z_i)|$. Nêu vì sao có thể chèn dấu.`),
    application:b('Independent random signs turn the difference of two samples into a centered signed sum whose two sample contributions have equal expectation.','Dấu ngẫu nhiên độc lập biến hiệu hai mẫu thành tổng có dấu đã tâm, trong đó hai đóng góp mẫu có kỳ vọng bằng nhau.'),
    formula:b(String.raw`For IID exchangeable pairs $(Z_i,Z'_i)$ and independent Rademacher $\sigma_i$, $E\sup_f|n^{-1}\sum_i(f(Z_i)-f(Z'_i))|\le2E\sup_f|n^{-1}\sum_i\sigma_i f(Z_i)|$.`,String.raw`Với cặp IID đổi chỗ được $(Z_i,Z'_i)$ và dấu Rademacher $\sigma_i$ độc lập, $E\sup_f|n^{-1}\sum_i(f(Z_i)-f(Z'_i))|\le2E\sup_f|n^{-1}\sum_i\sigma_i f(Z_i)|$.`),
    steps:[b('Exchangeability lets an independent sign swap each pair without changing the joint law, simultaneously for all f.','Tính đổi chỗ được cho phép dấu độc lập đổi vị trí từng cặp mà không đổi luật chung, đồng thời với mọi f.'),b(String.raw`Split the signed difference into the original-sample sum and the ghost-sample sum and apply the triangle inequality inside $\sup_f|\cdot|$.`,String.raw`Tách hiệu có dấu thành tổng mẫu gốc và tổng mẫu ghost, rồi áp tam giác bên trong $\sup_f|\cdot|$.`),b('The two resulting suprema have the same distribution, so their expectations add to twice the original-sample term.','Hai supremum thu được có cùng phân phối nên kỳ vọng cộng lại thành hai lần hạng mẫu gốc.')],
    primarySolution:[b(String.raw`For each i, $(Z_i,Z'_i)$ is exchangeable. Multiplying $f(Z_i)-f(Z'_i)$ by independent $\sigma_i\in\{-1,1\}$ preserves the joint distribution across all functions f.`,String.raw`Với mỗi i, $(Z_i,Z'_i)$ đổi chỗ được. Nhân $f(Z_i)-f(Z'_i)$ với $\sigma_i\in\{-1,1\}$ độc lập giữ nguyên luật chung cho mọi hàm f.`),b(String.raw`By this equality in distribution, the ghost difference has the same expected supremum as $n^{-1}\sum_i\sigma_i[f(Z_i)-f(Z'_i)]$.`,String.raw`Theo đẳng thức phân phối này, hiệu ghost có cùng supremum kỳ vọng với $n^{-1}\sum_i\sigma_i[f(Z_i)-f(Z'_i)]$.`),b(String.raw`For every f, $|A_f-B_f|\le|A_f|+|B_f|$, hence the supremum is at most $\sup_f|A_f|+\sup_f|B_f|$.`,String.raw`Với mọi f, $|A_f-B_f|\le|A_f|+|B_f|$, nên supremum không quá $\sup_f|A_f|+\sup_f|B_f|$.`),b('The ghost and original terms have the same law and expectation; adding them gives the factor 2. Absolute suprema remain in both terms.','Hạng ghost và mẫu gốc có cùng luật và kỳ vọng; cộng lại cho hệ số 2. Cả hai hạng đều giữ supremum trị tuyệt đối.')],
    companions:[
      {prompt:b(String.raw`For one pair of IID coin outcomes $Z,Z'$ and any fixed function f, show that $\sigma(f(Z)-f(Z'))$ has the same distribution as $f(Z)-f(Z')$ when σ is an independent fair sign.`,String.raw`Với một cặp kết quả đồng xu IID $Z,Z'$ và hàm f cố định, hãy chỉ ra $\sigma(f(Z)-f(Z'))$ có cùng phân phối với $f(Z)-f(Z')$ khi σ là dấu công bằng độc lập.`),solution:[b('The pair is exchangeable, so swapping Z and Z′ preserves its distribution.','Cặp đổi chỗ được nên hoán vị Z và Z′ giữ nguyên phân phối.'),b('When σ=−1 the difference changes sign, which is exactly the effect of swapping the pair; when σ=1 it stays unchanged.','Khi σ=−1 hiệu đổi dấu, đúng như hoán vị cặp; khi σ=1 hiệu giữ nguyên.'),b('Averaging the two equally likely cases preserves the original difference law.','Lấy trung bình hai trường hợp đồng khả năng giữ nguyên luật của hiệu ban đầu.') ]},
      {prompt:b(String.raw`If the original signed sum has supremum $A=0.3$ and the ghost signed sum has supremum $B=0.3$ in a realized sample, what triangle-inequality bound applies to the supremum of their difference?`,String.raw`Nếu tổng có dấu mẫu gốc có supremum $A=0.3$ và tổng có dấu ghost có supremum $B=0.3$ trong một mẫu hiện thực, cận tam giác nào áp dụng cho supremum hiệu của chúng?`),solution:[b('For every function, the absolute difference of the two signed sums is at most the sum of their absolute values.','Với mọi hàm, trị tuyệt đối hiệu của hai tổng có dấu không quá tổng trị tuyệt đối của chúng.'),b(String.raw`Taking suprema bounds the difference supremum by $A+B=0.3+0.3$.`,String.raw`Lấy supremum chặn supremum hiệu bởi $A+B=0.3+0.3$.`),b(String.raw`The resulting bound is 0.6; the factor two in expectation follows when the two sample terms have equal expectation.`,String.raw`Cận thu được là 0.6; hệ số hai trong kỳ vọng xuất hiện khi hai hạng mẫu có kỳ vọng bằng nhau.`)]},
      {prompt:b(String.raw`Why must both the ghost term and original term retain $\sup_f|\cdot|$ when using this argument for the absolute Rademacher complexity convention?`,String.raw`Vì sao cả hạng ghost và hạng mẫu gốc phải giữ $\sup_f|\cdot|$ khi dùng lập luận này theo quy ước absolute Rademacher complexity?`),solution:[b('The target quantity controls absolute deviations, including negative signed sums.','Đại lượng mục tiêu khống chế độ lệch tuyệt đối, kể cả tổng có dấu âm.'),b('The triangle inequality is $|A_f-B_f|\le|A_f|+|B_f|$ pointwise; dropping absolute values would not bound both signs.','Bất đẳng thức tam giác là $|A_f-B_f|\le|A_f|+|B_f|$ theo từng điểm; bỏ trị tuyệt đối sẽ không chặn cả hai dấu.'),b('Keeping the same absolute supremum also matches the complexity definition used in the subsequent excess-risk bound.','Giữ cùng supremum trị tuyệt đối cũng khớp định nghĩa complexity trong cận excess-risk tiếp theo.') ]},
    ],
    reviewNote:'Checked pair exchangeability jointly over the class, triangle-inequality placement inside the supremum, and preservation of absolute rather than one-sided complexity.',sourceIds:['o-cmu705'],
  },
  'm2-w086-e3': {
    title:b('Enumerate a four-sign empirical complexity','Liệt kê complexity empirical với bốn dấu'),
    prompt:b(String.raw`For n=4 and $\mathcal F=\{0,(1,1,1,1)\}$ on the sample, compute $E_\sigma\max(0,\sum_i\sigma_i)$ and the empirical Rademacher complexity. Enumerate sign sums with probabilities.`,String.raw`Với n=4 và $\mathcal F=\{0,(1,1,1,1)\}$ trên mẫu, tính $E_\sigma\max(0,\sum_i\sigma_i)$ và empirical Rademacher complexity. Hãy liệt kê tổng dấu cùng xác suất.`),
    application:b('For a class containing the zero predictor and one constant-on-sample predictor, the random sign sum can be counted exactly instead of bounded.','Với lớp chứa predictor không và một predictor hằng trên mẫu, có thể đếm chính xác tổng dấu ngẫu nhiên thay vì lấy cận.'),
    formula:b(String.raw`$\widehat{\mathfrak R}_{S}(\mathcal F)=E_\sigma\sup_{f\in\mathcal F}|n^{-1}\sum_i\sigma_if(Z_i)|$. Here the numerator is $E\max(0,S)$ for $S=\sum_{i=1}^4\sigma_i$.`,String.raw`$\widehat{\mathfrak R}_{S}(\mathcal F)=E_\sigma\sup_{f\in\mathcal F}|n^{-1}\sum_i\sigma_if(Z_i)|$. Ở đây tử số là $E\max(0,S)$ với $S=\sum_{i=1}^4\sigma_i$.`),
    steps:[b('Group the 16 equally likely sign vectors by their number of positive signs.','Nhóm 16 vector dấu đồng khả năng theo số dấu dương.'),b(String.raw`Convert each count to the sum values $S=-4,-2,0,2,4$ and apply $\max(0,S)$.`,String.raw`Đổi từng số lượng thành giá trị tổng $S=-4,-2,0,2,4$ rồi tính $\max(0,S)$.`),b('Average over all 16 outcomes, then divide by n=4 for empirical complexity.','Lấy trung bình trên cả 16 outcome rồi chia cho n=4 để được complexity empirical.')],
    primarySolution:[b(String.raw`The number of positive signs k has counts $\binom4k$, so S=2k−4 takes values −4,−2,0,2,4 with counts 1,4,6,4,1 out of 16.`,String.raw`Số dấu dương k có số cách $\binom4k$, nên S=2k−4 nhận −4,−2,0,2,4 với số lần 1,4,6,4,1 trên tổng 16.`),b(String.raw`The zero function and the constant-one function make the supremum $\max(0,S)$.`,String.raw`Hàm không và hàm hằng một làm supremum bằng $\max(0,S)$.`),b(String.raw`Its expectation is $[4(1)+2(4)]/16=12/16=0.75$.`,String.raw`Kỳ vọng là $[4(1)+2(4)]/16=12/16=0.75$.`),b(String.raw`The empirical complexity divides this numerator by n=4: $0.75/4=3/16=0.1875$. Negative-sum outcomes stay in the denominator even though their supremum contribution is zero.`,String.raw`Empirical complexity chia tử này cho n=4: $0.75/4=3/16=0.1875$. Các outcome tổng âm vẫn ở mẫu số dù đóng góp supremum bằng không.`)],
    companions:[
      {prompt:b(String.raw`For n=2 and $\mathcal F=\{0,(1,1)\}$, enumerate the Rademacher sums and compute empirical complexity.`,String.raw`Với n=2 và $\mathcal F=\{0,(1,1)\}$, hãy liệt kê tổng Rademacher và tính empirical complexity.`),solution:[b(String.raw`The four sign pairs yield sums −2,0,0,2, each with probability 1/4.`,String.raw`Bốn cặp dấu cho tổng −2,0,0,2, mỗi tổng xác suất 1/4.`),b(String.raw`The class supremum is $\max(0,S)$, whose expectation is $2(1/4)=0.5$.`,String.raw`Supremum lớp là $\max(0,S)$, có kỳ vọng $2(1/4)=0.5$.`),b(String.raw`Divide by n=2: empirical complexity is $0.25$.`,String.raw`Chia cho n=2: empirical complexity bằng $0.25$.`)]},
      {prompt:b(String.raw`For n=3 with the same zero and all-ones functions, compute $E\max(0,S)$ and the normalized empirical complexity.`,String.raw`Với n=3 và cùng hai hàm không, toàn-ones, hãy tính $E\max(0,S)$ và empirical complexity đã chuẩn hóa.`),solution:[b(String.raw`The sign sum has values −3,−1,1,3 with counts 1,3,3,1 out of 8.`,String.raw`Tổng dấu nhận −3,−1,1,3 với số lần 1,3,3,1 trên tổng 8.`),b(String.raw`Only positive values contribute: $E\max(0,S)=[3(1)+1(3)]/8=6/8=0.75$.`,String.raw`Chỉ giá trị dương đóng góp: $E\max(0,S)=[3(1)+1(3)]/8=6/8=0.75$.`),b(String.raw`The normalized complexity is $0.75/3=0.25$.`,String.raw`Complexity chuẩn hóa là $0.75/3=0.25$.`)]},
      {prompt:b(String.raw`For n=4, replace the all-ones vector by $(2,0,0,0)$. Compute the expected supremum and normalized complexity.`,String.raw`Với n=4, thay vector toàn-ones bằng $(2,0,0,0)$. Tính supremum kỳ vọng và complexity chuẩn hóa.`),solution:[b(String.raw`The nonzero predictor’s signed sum is $2\sigma_1$, so the supremum is $\max(0,2\sigma_1)$.`,String.raw`Tổng có dấu của predictor khác không là $2\sigma_1$, nên supremum là $\max(0,2\sigma_1)$.`),b(String.raw`It equals 2 when $\sigma_1=1$ and 0 when $\sigma_1=-1$, giving expectation 1.`,String.raw`Nó bằng 2 khi $\sigma_1=1$ và bằng 0 khi $\sigma_1=-1$, nên kỳ vọng bằng 1.`),b(String.raw`Divide by n=4 to obtain empirical complexity $1/4=0.25$.`,String.raw`Chia n=4 được empirical complexity $1/4=0.25$.`)]},
    ],
    reviewNote:'Checked binomial sign counts, zero-function effect on the absolute supremum, denominator 16, and final normalization by n.',sourceIds:['o-cmu705'],
  },
  'm2-w086-e4': {
    title:b('Pointwise convergence does not control a selected parameter','Hội tụ điểm không khống chế tham số được chọn'),
    prompt:b(String.raw`Pointwise convergence holds for every fixed $\theta\in[0,1]$, but an expanding grid $\Theta_n$ is chosen after observing the data. Explain why the fixed-parameter law of large numbers does not justify the selected $\hat\theta_n$ and give a valid uniform or sieve route.`,String.raw`Hội tụ điểm đúng với mọi $\theta\in[0,1]$, nhưng lưới mở rộng $\Theta_n$ được chọn sau khi xem dữ liệu. Giải thích vì sao luật số lớn cho tham số cố định không biện minh $\hat\theta_n$ được chọn và nêu cách đều hoặc sieve hợp lệ.`),
    application:b('Selecting the parameter after seeing its empirical fluctuation can choose an unusually favorable noise realization even when every prespecified parameter is consistent.','Chọn tham số sau khi xem dao động thực nghiệm có thể chọn nhiễu thuận lợi bất thường dù từng tham số xác định trước đều nhất quán.'),
    formula:b(String.raw`Pointwise: for each fixed $\theta$, $|P_nf_\theta-Pf_\theta|\to0$ in probability. Uniform control instead requires $\sup_{\theta\in\Theta_n}|P_nf_\theta-Pf_\theta|\to0$ (or a uniform sieve bound plus approximation control).`,String.raw`Theo điểm: với mỗi $\theta$ cố định, $|P_nf_\theta-Pf_\theta|\to0$ theo xác suất. Kiểm soát đều cần $\sup_{\theta\in\Theta_n}|P_nf_\theta-Pf_\theta|\to0$ (hoặc cận sieve đều cộng kiểm soát xấp xỉ).`),
    steps:[b('State the pointwise quantifier order: fix theta before taking the probability limit.','Nêu thứ tự lượng từ điểm: cố định theta trước khi lấy giới hạn xác suất.'),b('Observe that the selected theta-hat depends on the same sample noise and can target its largest fluctuation.','Nhận ra theta-hat được chọn phụ thuộc cùng nhiễu mẫu và có thể nhắm dao động lớn nhất.'),b('Require uniform control over the selected set, or a sieve argument that also controls approximation bias; sample splitting is another design with a changed efficiency.','Yêu cầu kiểm soát đều trên tập được chọn, hoặc lập luận sieve đồng thời chặn bias xấp xỉ; tách mẫu là thiết kế khác với hiệu quả thay đổi.')],
    primarySolution:[b('For any single theta fixed before observing the sample, a law of large numbers controls that one deviation.','Với từng theta cố định trước khi quan sát mẫu, luật số lớn khống chế độ lệch đó.'),b('The data-selected theta-hat is random and correlated with the observed deviations; pointwise convergence does not bound the maximum over a growing set.','Theta-hat được chọn từ dữ liệu là ngẫu nhiên và tương quan với độ lệch đã thấy; hội tụ điểm không chặn cực đại trên tập đang mở rộng.'),b('One valid route is a uniform law over each Theta_n with a complexity/concentration term tending to zero.','Một cách hợp lệ là luật đều trên từng Theta_n với hạng độ phức tạp/tập trung tiến về không.'),b('Alternatively use a sieve with uniform stochastic control on the sieve plus a separate approximation-bias argument for the target; sample splitting can select and evaluate independently but changes efficiency.','Hoặc dùng sieve với kiểm soát ngẫu nhiên đều trên sieve cộng lập luận bias xấp xỉ riêng cho target; tách mẫu cho phép chọn và đánh giá độc lập nhưng làm đổi hiệu quả.')],
    companions:[
      {prompt:b(String.raw`For each fixed integer j, an estimator $\hat\theta_{n,j}$ is consistent. The analyst reports $\hat\theta_{n,J_n}$ where $J_n$ is the index with the largest observed upward error among $n$ candidates. What guarantee is missing?`,String.raw`Với mỗi số nguyên j cố định, estimator $\hat\theta_{n,j}$ nhất quán. Nhà phân tích báo $\hat\theta_{n,J_n}$ với $J_n$ là chỉ số có sai số tăng lớn nhất trong $n$ ứng viên. Bảo đảm nào còn thiếu?`),solution:[b('Each fixed-j consistency statement controls one prespecified sequence, not the maximum across n candidates.','Mỗi phát biểu nhất quán j cố định khống chế một dãy xác định trước, không phải cực đại qua n ứng viên.'),b('Choosing J_n by the largest observed error directly selects a favorable noise fluctuation.','Chọn J_n theo sai số quan sát lớn nhất trực tiếp chọn dao động nhiễu thuận lợi.'),b('A uniform concentration bound over the candidate family, with its growing complexity controlled, is needed before evaluating this selected estimator.','Cần cận tập trung đồng đều trên họ ứng viên và khống chế độ phức tạp đang tăng trước khi đánh giá estimator được chọn.') ]},
      {prompt:b(String.raw`Suppose a sieve $\Theta_n$ has uniform stochastic error at most $a_n$ with high probability and approximation bias at most $b_n$. State a sufficient condition for consistency of its selected estimator.`,String.raw`Giả sử sieve $\Theta_n$ có sai số ngẫu nhiên đồng đều không quá $a_n$ với xác suất cao và bias xấp xỉ không quá $b_n$. Nêu điều kiện đủ để estimator được chọn nhất quán.`),solution:[b('Uniform stochastic control ensures every data-selected member in the sieve has deviation at most a_n on the event.','Kiểm soát ngẫu nhiên đều bảo đảm mọi phần tử sieve được chọn có độ lệch không quá a_n trên biến cố.'),b('Approximation bias b_n controls the gap between the best sieve target and the full target.','Bias xấp xỉ b_n khống chế khoảng cách giữa target tốt nhất trong sieve và target đầy đủ.'),b(String.raw`If $a_n\to0$ and $b_n\to0$ (with optimization error also tending to zero if present), the total estimation-plus-approximation error tends to zero.`,String.raw`Nếu $a_n\to0$ và $b_n\to0$ (cùng lỗi tối ưu nếu có cũng tiến về không), tổng lỗi ước lượng cộng xấp xỉ tiến về không.`)]},
      {prompt:b(String.raw`A sample is split into independent selection and evaluation halves. Explain what issue this can address for a data-selected theta and name one cost.`,String.raw`Mẫu được tách thành hai nửa chọn và đánh giá độc lập. Giải thích vấn đề nào của theta được chọn từ dữ liệu có thể được xử lý và nêu một chi phí.`),solution:[b('Select theta using the first half, then evaluate its empirical-population deviation using the independent second half.','Chọn theta bằng nửa đầu rồi đánh giá độ lệch empirical-population bằng nửa sau độc lập.'),b('Conditional on the selected theta, the evaluation sample was not used to choose it, reducing the direct winner’s-curse dependence.','Có điều kiện theo theta đã chọn, mẫu đánh giá không được dùng để chọn nó, giảm sự phụ thuộc trực tiếp gây winner’s curse.'),b('The evaluation sample is smaller and the estimand/design may change; splitting alone does not solve model misspecification or justify all inference.','Mẫu đánh giá nhỏ hơn và estimand/thiết kế có thể đổi; tách mẫu không tự sửa sai đặc tả hay biện minh mọi suy luận.') ]},
    ],
    reviewNote:'Checked pointwise quantifier order, data-selection dependence, and the separate stochastic and approximation requirements of sieve control.',sourceIds:['o-cmu705'],
  },
  'm2-w086-e5': {
    title:b('Memorization has zero training error and chance test error','Ghi nhớ có training error bằng không và test error ngẫu nhiên'),
    prompt:b(String.raw`Let $X_i$ be IID from a nonatomic law on $[0,1]$ and $Y_i\sim\operatorname{Bernoulli}(1/2)$ IID independently. Construct a sample-memorizing learner with zero training error and fresh-example 0–1 error 1/2; show an independent fresh X almost surely misses the finite training set.`,String.raw`Cho $X_i$ IID theo luật nonatomic trên $[0,1]$ và $Y_i\sim\operatorname{Bernoulli}(1/2)$ IID, độc lập. Hãy dựng learner ghi nhớ mẫu có training error bằng không và fresh-example 0–1 error 1/2; chứng minh X mới độc lập hầu chắc không thuộc tập training hữu hạn.`),
    application:b('An unrestricted lookup learner can fit every observed random label while making no useful prediction on a new input.','Learner tra bảng không bị hạn chế có thể khớp mọi nhãn ngẫu nhiên đã thấy nhưng không dự đoán hữu ích input mới.'),
    formula:b(String.raw`Define $f_S(x)=Y_i$ when $x=X_i$ (resolve ties by the smallest i) and $f_S(x)=0$ otherwise. Then $\widehat R_S(f_S)=0$ while $P(f_S(X)\ne Y\mid S)=1/2$ for a fresh independent pair.`,String.raw`Đặt $f_S(x)=Y_i$ khi $x=X_i$ (xử lý trùng bằng i nhỏ nhất) và $f_S(x)=0$ nếu không. Khi đó $\widehat R_S(f_S)=0$ nhưng $P(f_S(X)\ne Y\mid S)=1/2$ với cặp mới độc lập.`),
    steps:[b('Define a lookup rule on the finite training set and specify a tie convention.','Định nghĩa luật tra bảng trên tập training hữu hạn và nêu quy ước xử lý trùng.'),b('Verify pointwise that every training input receives its observed label.','Kiểm tra từng điểm training nhận đúng nhãn quan sát.'),b('Use nonatomicity and a finite union bound for a fresh input, then use label independence to compute its error.','Dùng tính nonatomic và union bound hữu hạn cho input mới, rồi dùng nhãn độc lập để tính lỗi.')],
    primarySolution:[b('Set f_S(X_i)=Y_i for each training index, resolving duplicate inputs by the smallest index; set f_S(x)=0 elsewhere. Nonatomic sampling makes duplicate inputs probability zero.','Đặt f_S(X_i)=Y_i ở mỗi chỉ số training, xử lý input trùng bằng chỉ số nhỏ nhất; đặt f_S(x)=0 ở nơi khác. Lấy mẫu nonatomic làm xác suất trùng bằng không.'),b('Every training observation is classified correctly, so empirical 0–1 risk is exactly zero.','Mọi quan sát training được phân loại đúng nên empirical 0–1 risk bằng đúng không.'),b(String.raw`Given S, an independent fresh X has $P(X\in\{X_1,\ldots,X_n\}\mid S)=0$ because the law is nonatomic and the set is finite.`,String.raw`Cho S, X mới độc lập có $P(X\in\{X_1,\ldots,X_n\}\mid S)=0$ vì luật nonatomic và tập hữu hạn.`),b('Thus f_S(X)=0 almost surely, while fresh Y is independent Bernoulli(1/2); prediction error is 1/2. Zero training error alone does not control capacity or generalization.','Do đó f_S(X)=0 hầu chắc, trong khi Y mới độc lập Bernoulli(1/2); xác suất dự đoán sai là 1/2. Training error bằng không riêng lẻ không khống chế capacity hay tổng quát hóa.')],
    companions:[
      {prompt:b(String.raw`A lookup classifier memorizes n distinct training inputs and predicts 1 off the training set. Training labels are all fitted exactly; fresh labels are independent Bernoulli(1/2). Find training and fresh error.`,String.raw`Bộ phân loại tra bảng ghi nhớ n input training khác nhau và dự đoán 1 ngoài tập training. Nhãn training khớp hoàn toàn; nhãn mới độc lập Bernoulli(1/2). Tìm training error và fresh error.`),solution:[b('Each training input is assigned its own observed label, so the empirical error is zero.','Mỗi input training được gán nhãn quan sát của chính nó nên empirical error bằng không.'),b('A nonatomic fresh input lies outside the finite memorized set almost surely.','Input mới nonatomic nằm ngoài tập ghi nhớ hữu hạn hầu chắc.'),b('The fixed off-set prediction 1 disagrees with a fair independent Bernoulli label with probability 1/2.','Dự đoán cố định 1 ngoài tập bất đồng với nhãn Bernoulli công bằng độc lập với xác suất 1/2.') ]},
      {prompt:b(String.raw`If fresh labels are Bernoulli(p) but the memorizing rule predicts 0 off the training set, compute its fresh error and evaluate p=0.3.`,String.raw`Nếu nhãn mới Bernoulli(p) nhưng luật ghi nhớ dự đoán 0 ngoài tập training, hãy tính fresh error và đánh giá tại p=0.3.`),solution:[b('A nonatomic fresh input misses all memorized inputs with probability one.','Input nonatomic mới trượt khỏi mọi input đã ghi nhớ với xác suất một.'),b('The rule errs exactly when the fresh label is 1, an event of probability p.','Luật mắc lỗi đúng khi nhãn mới bằng 1, biến cố xác suất p.'),b(String.raw`Thus fresh risk is p; at $p=0.3$ it equals 0.3 despite zero training error.`,String.raw`Vậy fresh risk bằng p; khi $p=0.3$ nó bằng 0.3 dù training error bằng không.`)]},
      {prompt:b(String.raw`For a fresh nonatomic X and fixed training inputs $X_1,\ldots,X_n$, prove $P(X\in\{X_1,\ldots,X_n\}\mid S)=0$.`,String.raw`Với X nonatomic mới và các input training cố định $X_1,\ldots,X_n$, chứng minh $P(X\in\{X_1,\ldots,X_n\}\mid S)=0$.`),solution:[b('For each fixed i, nonatomicity gives P(X=X_i|S)=0.','Với mỗi i cố định, tính nonatomic cho P(X=X_i|S)=0.'),b('The event of hitting any stored point is the union of these n equality events.','Biến cố trùng bất kỳ điểm lưu nào là hợp của n biến cố bằng nhau.'),b(String.raw`A finite union bound gives $P(X\in\{X_1,\ldots,X_n\}\mid S)\le\sum_{i=1}^n0=0$.`,String.raw`Union bound hữu hạn cho $P(X\in\{X_1,\ldots,X_n\}\mid S)\le\sum_{i=1}^n0=0$.`)]},
    ],
    reviewNote:'Checked the sample-dependent lookup definition, tie handling, nonatomic fresh-input argument, and independent Bernoulli test-risk calculation.',sourceIds:['o-cmu705'],
  },
  'm2-w087-e1': {
    title:b('Linear-class Rademacher complexity','Rademacher complexity của lớp tuyến tính'),
    prompt:b(String.raw`For $\mathcal F_B=\{x\mapsto w^\top x:\|w\|_2\le B\}$ and a fixed sample with $\|x_i\|_2\le R$, derive $\widehat{\mathfrak R}_{abs}(\mathcal F_B)\le BR/\sqrt n$. Identify duality and the sign second moment.`,String.raw`Với $\mathcal F_B=\{x\mapsto w^\top x:\|w\|_2\le B\}$ và mẫu cố định có $\|x_i\|_2\le R$, hãy suy $\widehat{\mathfrak R}_{abs}(\mathcal F_B)\le BR/\sqrt n$. Nêu vai trò đối ngẫu và moment bậc hai của dấu.`),
    application:b('A norm constraint limits how strongly a linear predictor can align with the random signed sum of observed features.','Ràng buộc chuẩn giới hạn mức predictor tuyến tính có thể thẳng hàng với tổng feature mang dấu ngẫu nhiên.'),
    formula:b(String.raw`$\widehat{\mathfrak R}_{abs}=E_\sigma\sup_{\|w\|_2\le B}|n^{-1}\sum_i\sigma_iw^\top x_i|\le BR/\sqrt n$, for a fixed sample with $\|x_i\|_2\le R$.`,String.raw`$\widehat{\mathfrak R}_{abs}=E_\sigma\sup_{\|w\|_2\le B}|n^{-1}\sum_i\sigma_iw^\top x_i|\le BR/\sqrt n$, với mẫu cố định có $\|x_i\|_2\le R$.`),
    steps:[b(String.raw`Move the supremum through the linear form and use $\sup_{\|w\|_2\le B}|w^\top v|=B\|v\|_2$.`,String.raw`Đưa supremum vào dạng tuyến tính và dùng $\sup_{\|w\|_2\le B}|w^\top v|=B\|v\|_2$.`),b('Apply Jensen/Cauchy–Schwarz to bound the expected norm by the square root of its second moment.','Áp Jensen/Cauchy–Schwarz chặn kỳ vọng chuẩn bằng căn moment bậc hai.'),b('Expand the squared norm; independent Rademacher signs cancel cross terms, leaving the sum of feature norms squared.','Khai triển chuẩn bình phương; dấu Rademacher độc lập triệt tiêu hạng chéo, còn tổng bình phương chuẩn feature.')],
    primarySolution:[b(String.raw`Let $V=\sum_i\sigma_ix_i$. By Euclidean duality, $\widehat{\mathfrak R}_{abs}=(B/n)E_\sigma\|V\|_2$.`,String.raw`Đặt $V=\sum_i\sigma_ix_i$. Theo đối ngẫu Euclid, $\widehat{\mathfrak R}_{abs}=(B/n)E_\sigma\|V\|_2$.`),b(String.raw`Jensen gives $E\|V\|_2\le\sqrt{E\|V\|_2^2}$. Expand $\|V\|_2^2=\sum_{i,j}\sigma_i\sigma_jx_i^\top x_j$.`,String.raw`Jensen cho $E\|V\|_2\le\sqrt{E\|V\|_2^2}$. Khai triển $\|V\|_2^2=\sum_{i,j}\sigma_i\sigma_jx_i^\top x_j$.`),b('For i≠j, independence and zero-mean signs give E[σ_iσ_j]=0; for i=j the expectation is 1.','Với i≠j, tính độc lập và dấu trung bình không cho E[σ_iσ_j]=0; với i=j kỳ vọng bằng 1.'),b(String.raw`Thus $E\|V\|_2^2=\sum_i\|x_i\|_2^2\le nR^2$, so $\widehat{\mathfrak R}_{abs}\le(B/n)\sqrt{nR^2}=BR/\sqrt n$.`,String.raw`Vậy $E\|V\|_2^2=\sum_i\|x_i\|_2^2\le nR^2$, nên $\widehat{\mathfrak R}_{abs}\le(B/n)\sqrt{nR^2}=BR/\sqrt n$.`)],
    companions:[
      {prompt:b(String.raw`For B=2, R=3 and n=16, evaluate the linear-class complexity bound.`,String.raw`Với B=2, R=3 và n=16, hãy tính cận complexity lớp tuyến tính.`),solution:[b(String.raw`The bound is $BR/\sqrt n$.`,String.raw`Cận là $BR/\sqrt n$.`),b(String.raw`Substitute the values: $2(3)/\sqrt{16}=6/4$.`,String.raw`Thế giá trị: $2(3)/\sqrt{16}=6/4$.`),b(String.raw`The empirical Rademacher complexity is at most 1.5.`,String.raw`Empirical Rademacher complexity không quá 1.5.`)]},
      {prompt:b(String.raw`For B=1, R=2 and n=4, compute the bound and state which feature assumption is being used.`,String.raw`Với B=1, R=2 và n=4, hãy tính cận và nêu giả thiết feature nào đang dùng.`),solution:[b('The fixed sample must satisfy norm at most R for every observation.','Mẫu cố định phải thỏa chuẩn mỗi quan sát không quá R.'),b(String.raw`The complexity bound is $BR/\sqrt n=1(2)/\sqrt4$.`,String.raw`Cận complexity là $BR/\sqrt n=1(2)/\sqrt4$.`),b(String.raw`It equals 1; the result relies on $\|x_i\|_2\le2$ for all four sample points.`,String.raw`Kết quả bằng 1; suy ra này dựa vào $\|x_i\|_2\le2$ cho cả bốn điểm mẫu.`)]},
      {prompt:b(String.raw`For n=2, let both scalar features be $x_1=x_2=1$ and B=2. Compute the empirical absolute complexity exactly and compare with $BR/\sqrt n$.`,String.raw`Với n=2, cho hai feature vô hướng $x_1=x_2=1$ và B=2. Tính chính xác absolute complexity empirical rồi so với $BR/\sqrt n$.`),solution:[b(String.raw`The signed sum is $\sigma_1+\sigma_2$, whose absolute value is 2 with probability 1/2 and 0 with probability 1/2.`,String.raw`Tổng có dấu là $\sigma_1+\sigma_2$, trị tuyệt đối bằng 2 với xác suất 1/2 và bằng 0 với xác suất 1/2.`),b(String.raw`Its expected absolute value is 1; multiplying by B/n gives $2(1)/2=1$.`,String.raw`Trị tuyệt đối kỳ vọng là 1; nhân B/n được $2(1)/2=1$.`),b(String.raw`The norm bound gives $BR/\sqrt n=2/\sqrt2\approx1.414$, a valid but looser upper bound.`,String.raw`Cận chuẩn cho $BR/\sqrt n=2/\sqrt2\approx1.414$, là cận trên hợp lệ nhưng lỏng hơn.`)]},
    ],
    reviewNote:'Checked the dual norm identity, cross-term cancellation under independent signs, and the sample-dependent norm assumption.',sourceIds:['o-cmu705'],
  },
  'm2-w087-e2': {
    title:b('ERM excess-risk telescoping decomposition','Phép tách tổng khử excess-risk của ERM'),
    prompt:b(String.raw`Let $g_f(z)=\ell(f,z)$, and let $\hat f$ be an exact empirical minimizer over a measurable class. For any $\varepsilon>0$, choose $f_\varepsilon$ with $R(f_\varepsilon)\le\inf_{f\in\mathcal F}R(f)+\varepsilon$. Insert empirical risks to prove $R(\hat f)-\inf_FR\le2\sup_g|\widehat R-R|+\varepsilon$, then let $\varepsilon\downarrow0$.`,String.raw`Cho $g_f(z)=\ell(f,z)$ và $\hat f$ là nghiệm cực tiểu empirical chính xác trên lớp đo được. Với mọi $\varepsilon>0$, chọn $f_\varepsilon$ thỏa $R(f_\varepsilon)\le\inf_{f\in\mathcal F}R(f)+\varepsilon$. Hãy chèn risk empirical để chứng minh $R(\hat f)-\inf_FR\le2\sup_g|\widehat R-R|+\varepsilon$, rồi cho $\varepsilon\downarrow0$.`),
    application:b('A population-risk minimizer may fail to exist, but an approximate minimizer suffices to compare the empirical ERM with the infimum.','Minimizer risk quần thể có thể không tồn tại, nhưng minimizer xấp xỉ đủ để so ERM thực nghiệm với infimum.'),
    formula:b(String.raw`For exact empirical ERM $\hat f$ and any $\varepsilon$-optimal population comparator $f_\varepsilon$, $R(\hat f)-\inf_FR\le2\sup_{f\in\mathcal F}|R(f)-\widehat R(f)|+\varepsilon$.`,String.raw`Với ERM empirical chính xác $\hat f$ và comparator quần thể $\varepsilon$-tối ưu bất kỳ $f_\varepsilon$, $R(\hat f)-\inf_FR\le2\sup_{f\in\mathcal F}|R(f)-\widehat R(f)|+\varepsilon$.`),
    steps:[b('Choose a comparator within epsilon of the population infimum, without assuming it is attained.','Chọn comparator cách infimum quần thể không quá epsilon mà không giả sử infimum đạt được.'),b('Insert empirical risks at the ERM and comparator; the middle empirical difference is nonpositive.','Chèn risk empirical tại ERM và comparator; hiệu empirical ở giữa không dương.'),b('Bound the two endpoint deviations by the same supremum, then send epsilon to zero.','Chặn hai sai lệch đầu mút bằng cùng supremum rồi cho epsilon về không.')],
    primarySolution:[b(String.raw`Choose $f_\varepsilon$ with $R(f_\varepsilon)\le\inf_FR+\varepsilon$. Then $R(\hat f)-\inf_FR\le R(\hat f)-R(f_\varepsilon)+\varepsilon$.`,String.raw`Chọn $f_\varepsilon$ có $R(f_\varepsilon)\le\inf_FR+\varepsilon$. Khi đó $R(\hat f)-\inf_FR\le R(\hat f)-R(f_\varepsilon)+\varepsilon$.`),b(String.raw`Insert empirical risks: $R(\hat f)-R(f_\varepsilon)=[R(\hat f)-\widehat R(\hat f)]+[\widehat R(\hat f)-\widehat R(f_\varepsilon)]+[\widehat R(f_\varepsilon)-R(f_\varepsilon)]$.`,String.raw`Chèn risk empirical: $R(\hat f)-R(f_\varepsilon)=[R(\hat f)-\widehat R(\hat f)]+[\widehat R(\hat f)-\widehat R(f_\varepsilon)]+[\widehat R(f_\varepsilon)-R(f_\varepsilon)]$.`),b('The middle term is at most zero because fhat minimizes empirical risk.','Hạng ở giữa không quá không vì fhat tối thiểu hóa risk empirical.'),b(String.raw`Each endpoint is at most $\sup_f|R(f)-\widehat R(f)|$. Add epsilon and let $\varepsilon\downarrow0$ to obtain the bound; this avoids assuming a population minimizer exists.`,String.raw`Mỗi hạng đầu mút không quá $\sup_f|R(f)-\widehat R(f)|$. Cộng epsilon rồi cho $\varepsilon\downarrow0$ được cận; cách này không giả sử minimizer quần thể tồn tại.`)],
    companions:[
      {prompt:b(String.raw`If the uniform deviation $\sup_f|R(f)-\widehat R(f)|$ is at most 0.03 and an approximate population comparator is within ε=0.01 of $\inf_FR$, what ERM excess bound follows?`,String.raw`Nếu độ lệch đều $\sup_f|R(f)-\widehat R(f)|$ không quá 0.03 và comparator quần thể gần ε=0.01 so với $\inf_FR$, cận excess ERM nào suy ra?`),solution:[b(String.raw`The two endpoint deviations contribute at most $2(0.03)=0.06$.`,String.raw`Hai sai lệch đầu mút đóng góp không quá $2(0.03)=0.06$.`),b(String.raw`Add the comparator approximation allowance 0.01.`,String.raw`Cộng dung sai xấp xỉ comparator 0.01.`),b(String.raw`The excess is at most $0.06+0.01=0.07$.`,String.raw`Excess không quá $0.06+0.01=0.07$.`)]},
      {prompt:b(String.raw`An empirical ERM has population risk 0.4 and a chosen comparator has population risk 0.35; the uniform deviation is 0.03. Find the bound obtained by the telescoping argument using this comparator.`,String.raw`ERM empirical có risk quần thể 0.4 và comparator chọn có risk quần thể 0.35; độ lệch đều là 0.03. Tìm cận từ lập luận tổng khử dùng comparator này.`),solution:[b(String.raw`The realized excess over this comparator is $0.4-0.35=0.05$.`,String.raw`Excess thực tế so với comparator là $0.4-0.35=0.05$.`),b(String.raw`The two empirical-population endpoints are each bounded by 0.03; the middle empirical difference is nonpositive.`,String.raw`Hai hạng empirical-population đầu mút mỗi hạng bị chặn bởi 0.03; hiệu empirical ở giữa không dương.`),b(String.raw`Thus the derived upper bound is $0.03+0.03=0.06$, which covers the observed gap $0.05$; these numbers are compatible with the stated assumptions.`,String.raw`Vì vậy cận trên suy ra là $0.03+0.03=0.06$, đủ bao phủ khoảng cách quan sát $0.05$; các số này tương thích với giả thiết đã nêu.`)]},
      {prompt:b(String.raw`If $\mathcal F$ has no population-risk minimizer but has finite infimum, why is $f_\varepsilon$ enough for the proof?`,String.raw`Nếu $\mathcal F$ không có minimizer risk quần thể nhưng infimum hữu hạn, vì sao $f_\varepsilon$ đủ cho chứng minh?`),solution:[b('By definition of an infimum, for every positive epsilon there is a class member within epsilon of it.','Theo định nghĩa infimum, với mọi epsilon dương có phần tử lớp cách nó không quá epsilon.'),b('The telescoping decomposition compares fhat with that actual member and never needs attainment of the infimum.','Phép tách tổng khử so fhat với phần tử thực đó và không cần infimum đạt được.'),b('The resulting inequality holds for every epsilon>0; taking the limit yields the bound against the infimum itself.','Bất đẳng thức đúng với mọi epsilon>0; lấy giới hạn cho cận so với chính infimum.') ]},
    ],
    reviewNote:'Checked the sign of the empirical ERM middle term and the epsilon-comparator limit; the numeric fixture is consistent with the resulting upper bound.',sourceIds:['o-cmu705'],
  },
  'm2-w087-e3': {
    title:b('Contraction bound for squared loss','Cận co cho squared loss'),
    prompt:b(String.raw`Let $\|w\|_2\le B$, $\|x\|_2\le R$, $|y|\le Y$, and $\ell_y(u)=(u-y)^2$. Center by $\ell_y(0)$, find the Lipschitz constant on $|u|\le BR$, and use absolute contraction plus the linear-class bound to give an expected ERM excess bound. State each factor.`,String.raw`Cho $\|w\|_2\le B$, $\|x\|_2\le R$, $|y|\le Y$ và $\ell_y(u)=(u-y)^2$. Định tâm bằng $\ell_y(0)$, tìm hằng số Lipschitz trên $|u|\le BR$, rồi dùng bất đẳng thức co tuyệt đối cùng cận lớp tuyến tính để cho cận excess ERM kỳ vọng. Nêu từng hệ số.`),
    application:b('Bounding squared-loss generalization requires restricting predictions and accounting for the target range before applying a contraction inequality.','Chặn tổng quát hóa squared-loss cần giới hạn dự báo và tính đến khoảng target trước khi dùng bất đẳng thức co.'),
    formula:b(String.raw`Set $\psi_y(u)=(u-y)^2-y^2$. On $|u|\le BR$, $\psi_y(0)=0$ and $|\psi'_y(u)|=|2(u-y)|\le L=2(BR+Y)$. Under the stated IID/bounded assumptions, the excess bound is $4\cdot2L\cdot BR/\sqrt n=16BR(BR+Y)/\sqrt n$.`,String.raw`Đặt $\psi_y(u)=(u-y)^2-y^2$. Trên $|u|\le BR$, $\psi_y(0)=0$ và $|\psi'_y(u)|=|2(u-y)|\le L=2(BR+Y)$. Dưới giả thiết IID/bị chặn đã nêu, cận excess là $4\cdot2L\cdot BR/\sqrt n=16BR(BR+Y)/\sqrt n$.`),
    steps:[b(String.raw`Subtract $\ell_y(0)=y^2$ so the centered transform vanishes at zero; the offset is independent of the candidate and cancels from excess risk.`,String.raw`Trừ $\ell_y(0)=y^2$ để phép biến đổi đã tâm bằng không tại không; offset không phụ thuộc ứng viên và triệt tiêu trong excess risk.`),b(String.raw`Differentiate: $\psi'_y(u)=2(u-y)$; $|u|\le BR$ and $|y|\le Y$ imply Lipschitz constant $L=2(BR+Y)$.`,String.raw`Lấy đạo hàm: $\psi'_y(u)=2(u-y)$; $|u|\le BR$, $|y|\le Y$ suy ra hằng số Lipschitz $L=2(BR+Y)$.`),b('Apply the excess-risk factor 4, absolute-contraction factor 2L, and the linear complexity BR/√n.','Áp hệ số excess-risk 4, hệ số co tuyệt đối 2L và complexity tuyến tính BR/√n.')],
    primarySolution:[b(String.raw`Predictions obey $|w^\top x|\le\|w\|_2\|x\|_2\le BR$. Define $\psi_y(u)=(u-y)^2-y^2=u^2-2uy$.`,String.raw`Dự báo thỏa $|w^\top x|\le\|w\|_2\|x\|_2\le BR$. Đặt $\psi_y(u)=(u-y)^2-y^2=u^2-2uy$.`),b(String.raw`The candidate-independent $y^2$ does not change empirical minimizers or excess population risk, though each separate empirical-population deviation shifts by $(P-P_n)y^2$.`,String.raw`Hạng $y^2$ không phụ thuộc ứng viên nên không đổi nghiệm empirical hay excess risk quần thể, dù từng độ lệch empirical-population riêng thay đổi một lượng $(P-P_n)y^2$.`),b(String.raw`Now $\psi_y(0)=0$ and $|\psi'_y(u)|=2|u-y|\le2(BR+Y)=L$ throughout the prediction range.`,String.raw`Lúc này $\psi_y(0)=0$ và $|\psi'_y(u)|=2|u-y|\le2(BR+Y)=L$ trên toàn miền dự báo.`),b(String.raw`The expected ERM excess factor is 4; absolute contraction contributes $2L$; the linear class contributes $BR/\sqrt n$. Thus $4(2L)(BR/\sqrt n)=8LBR/\sqrt n=16BR(BR+Y)/\sqrt n$. This is a loose bound requiring IID sampling and the stated boundedness.`,String.raw`Hệ số excess ERM kỳ vọng là 4; co tuyệt đối đóng góp $2L$; lớp tuyến tính đóng góp $BR/\sqrt n$. Vì vậy $4(2L)(BR/\sqrt n)=8LBR/\sqrt n=16BR(BR+Y)/\sqrt n$. Đây là cận lỏng cần lấy mẫu IID và các giới hạn đã nêu.`)],
    companions:[
      {prompt:b(String.raw`Let B=2, R=1, Y=3 and n=400. Compute L and the displayed squared-loss excess bound.`,String.raw`Cho B=2, R=1, Y=3 và n=400. Tính L và cận excess squared-loss đã nêu.`),solution:[b(String.raw`The prediction radius is $BR=2$, so $L=2(BR+Y)=2(2+3)=10$.`,String.raw`Bán kính dự báo là $BR=2$, nên $L=2(BR+Y)=2(2+3)=10$.`),b(String.raw`Substitute into $8LBR/\sqrt n$: $8(10)(2)/20$.`,String.raw`Thế vào $8LBR/\sqrt n$: $8(10)(2)/20$.`),b(String.raw`The bound equals 8. It is an expectation bound and may be loose.`,String.raw`Cận bằng 8. Đây là cận kỳ vọng và có thể lỏng.`)]},
      {prompt:b(String.raw`For B=1, R=2, Y=1 and n=144, calculate the Lipschitz constant and the excess bound.`,String.raw`Với B=1, R=2, Y=1 và n=144, hãy tính hằng số Lipschitz và cận excess.`),solution:[b(String.raw`The prediction radius is $BR=2$, so $L=2(2+1)=6$.`,String.raw`Bán kính dự báo là $BR=2$, nên $L=2(2+1)=6$.`),b(String.raw`The bound is $8LBR/\sqrt n=8(6)(2)/12$.`,String.raw`Cận là $8LBR/\sqrt n=8(6)(2)/12$.`),b(String.raw`It evaluates to 8; the bounded-output assumption $|y|\le1$ is needed for the stated L.`,String.raw`Kết quả bằng 8; giả thiết output bị chặn $|y|\le1$ cần cho L đã nêu.`)]},
      {prompt:b(String.raw`For B=1, R=1, Y=0.5 and n=100, calculate L and the resulting bound; identify the dependence on target magnitude.`,String.raw`Với B=1, R=1, Y=0.5 và n=100, hãy tính L và cận thu được; nêu sự phụ thuộc vào độ lớn target.`),solution:[b(String.raw`Here $BR=1$ and $L=2(1+0.5)=3$.`,String.raw`Ở đây $BR=1$ và $L=2(1+0.5)=3$.`),b(String.raw`The bound is $8LBR/\sqrt n=8(3)(1)/10$.`,String.raw`Cận là $8LBR/\sqrt n=8(3)(1)/10$.`),b(String.raw`It is 2.4; increasing Y increases the Lipschitz constant and therefore this bound linearly.`,String.raw`Kết quả là 2.4; tăng Y làm tăng hằng số Lipschitz và vì vậy cận này tăng tuyến tính.`)]},
    ],
    reviewNote:'Checked the prediction range by Cauchy–Schwarz, centered derivative bound, distinct factors 4 and 2L, and the offset’s effect on deviations versus excess risk.',sourceIds:['o-cmu705'],
  },
  'm2-w087-e4': {
    title:b('Nested capacity and approximation error','Capacity lồng và sai số xấp xỉ'),
    prompt:b(String.raw`For nested classes $\mathcal F_1\subset\mathcal F_2$, write an excess-risk bound as approximation error plus estimation complexity. Explain which term cannot worsen under nesting and why total risk need not improve.`,String.raw`Với các lớp lồng nhau $\mathcal F_1\subset\mathcal F_2$, hãy viết cận excess-risk thành sai số xấp xỉ cộng complexity ước lượng. Giải thích hạng nào không thể xấu đi khi lồng và vì sao tổng risk chưa chắc cải thiện.`),
    application:b('Adding candidate models improves the best attainable population fit but can make simultaneous statistical control harder.','Thêm mô hình ứng viên cải thiện độ khớp quần thể tốt nhất nhưng có thể làm kiểm soát thống kê đồng thời khó hơn.'),
    formula:b(String.raw`A typical bound is $\inf_{f\in\mathcal F}R(f)-R^*+4E\widehat{\mathfrak R}_{abs}(\ell\circ\mathcal F)$, plus any optimization allowance. If $\mathcal F_1\subset\mathcal F_2$, then $\inf_{\mathcal F_2}R\le\inf_{\mathcal F_1}R$.`,String.raw`Một cận điển hình là $\inf_{f\in\mathcal F}R(f)-R^*+4E\widehat{\mathfrak R}_{abs}(\ell\circ\mathcal F)$, cộng dung sai tối ưu nếu có. Nếu $\mathcal F_1\subset\mathcal F_2$ thì $\inf_{\mathcal F_2}R\le\inf_{\mathcal F_1}R$.`),
    steps:[b('Separate the best-in-class approximation gap from sample-dependent complexity and optimization error.','Tách khoảng xấp xỉ tốt nhất trong lớp khỏi complexity phụ thuộc mẫu và lỗi tối ưu.'),b('Use set inclusion to compare infimum risks across the nested classes.','Dùng quan hệ tập con để so infimum risk giữa các lớp lồng nhau.'),b('Do not infer the total bound or realized test risk from the approximation term alone; complexity may rise.','Không suy cận tổng hay test risk thực tế chỉ từ hạng xấp xỉ; complexity có thể tăng.')],
    primarySolution:[b(String.raw`For each class, decompose excess into approximation $\inf_{f\in\mathcal F}R(f)-R^*$ and an estimation term such as $4E\widehat{\mathfrak R}_{abs}(\ell\circ\mathcal F)$, with optimization error added separately if needed.`,String.raw`Với mỗi lớp, tách excess thành xấp xỉ $\inf_{f\in\mathcal F}R(f)-R^*$ và hạng ước lượng như $4E\widehat{\mathfrak R}_{abs}(\ell\circ\mathcal F)$, cộng lỗi tối ưu riêng nếu cần.`),b(String.raw`Because $\mathcal F_1\subset\mathcal F_2$, minimizing over the larger set gives $\inf_{\mathcal F_2}R\le\inf_{\mathcal F_1}R$.`,String.raw`Vì $\mathcal F_1\subset\mathcal F_2$, lấy infimum trên tập lớn cho $\inf_{\mathcal F_2}R\le\inf_{\mathcal F_1}R$.`),b('Thus the approximation term cannot worsen when the class expands.','Vì vậy hạng xấp xỉ không thể xấu đi khi lớp mở rộng.'),b('The complexity/optimization terms need not decrease and can outweigh the approximation gain, so neither the total displayed bound nor realized test risk must improve.','Các hạng complexity/tối ưu không nhất thiết giảm và có thể lấn át lợi ích xấp xỉ, nên cả cận tổng lẫn test risk thực tế đều không nhất thiết cải thiện.')],
    companions:[
      {prompt:b(String.raw`Class $\mathcal F_1$ has approximation error 0.20 and estimation term 0.02; nested $\mathcal F_2$ has approximation error 0.10 and estimation term 0.15. Compare the displayed sums.`,String.raw`Lớp $\mathcal F_1$ có sai số xấp xỉ 0.20 và hạng ước lượng 0.02; lớp lồng $\mathcal F_2$ có sai số xấp xỉ 0.10 và hạng ước lượng 0.15. Hãy so tổng hiển thị.`),solution:[b(String.raw`The smaller-class sum is $0.20+0.02=0.22$.`,String.raw`Tổng lớp nhỏ là $0.20+0.02=0.22$.`),b(String.raw`The larger-class sum is $0.10+0.15=0.25$.`,String.raw`Tổng lớp lớn là $0.10+0.15=0.25$.`),b('Approximation improves by 0.10 but complexity increases by 0.13, so the displayed total worsens by 0.03.','Xấp xỉ cải thiện 0.10 nhưng complexity tăng 0.13, nên tổng hiển thị xấu đi 0.03.') ]},
      {prompt:b(String.raw`The best risks are 0.4 in $\mathcal F_1$ and 0.3 in nested $\mathcal F_2$, while $R^*=0.1$. Compute approximation errors and explain what nesting guarantees.`,String.raw`Risk tốt nhất là 0.4 trong $\mathcal F_1$ và 0.3 trong $\mathcal F_2$ lồng nhau, còn $R^*=0.1$. Tính sai số xấp xỉ và giải thích bảo đảm nào do lồng lớp.`),solution:[b(String.raw`The first approximation error is $0.4-0.1=0.3$.`,String.raw`Sai số xấp xỉ thứ nhất là $0.4-0.1=0.3$.`),b(String.raw`The second is $0.3-0.1=0.2$, lower by 0.1.`,String.raw`Sai số thứ hai là $0.3-0.1=0.2$, thấp hơn 0.1.`),b('Nesting guarantees only that the best attainable risk cannot increase; it does not constrain the estimation-complexity term.','Lồng lớp chỉ bảo đảm risk tốt nhất đạt được không tăng; nó không chặn hạng complexity ước lượng.') ]},
      {prompt:b(String.raw`A larger model class lowers training loss but increases its Rademacher complexity bound. Can one conclude test risk fell? State what comparison is required.`,String.raw`Lớp mô hình lớn hơn giảm training loss nhưng tăng cận Rademacher complexity. Có thể kết luận test risk giảm không? Nêu phép so sánh cần thiết.`),solution:[b('No. Lower empirical loss alone is not population performance.','Không. Training loss thấp hơn riêng lẻ không phải hiệu năng quần thể.'),b('Compare approximation, estimation/complexity and optimization terms for both classes.','So sánh các hạng xấp xỉ, ước lượng/complexity và tối ưu của cả hai lớp.'),b('Even a smaller theoretical bound is a guarantee summary, not a deterministic statement about the realized test sample; evaluate on an untouched test set for empirical comparison.','Ngay cả cận lý thuyết nhỏ hơn cũng là tóm tắt bảo đảm, không phải mệnh đề xác định về mẫu test thực tế; cần đánh giá trên tập test chưa đụng để so thực nghiệm.') ]},
    ],
    reviewNote:'Checked the nested-set direction for infimum risk and kept approximation, estimation complexity, optimization and realized test performance distinct.',sourceIds:['o-cmu705'],
  },
  'm2-w087-e5': {
    title:b('A large feature defeats an unqualified fixed-radius rate','Feature lớn phá tốc độ bán kính cố định không điều kiện'),
    prompt:b(String.raw`For $\mathcal F_B$ with $\|w\|\le B$, suppose one sample feature has norm n and all others are zero. Evaluate $(B/n)E|\sigma_1n|$, explain why $BR/\sqrt n$ with fixed R is unavailable, and give a valid repair.`,String.raw`Với $\mathcal F_B$ có $\|w\|\le B$, giả sử một feature mẫu có chuẩn n còn các feature khác bằng không. Tính $(B/n)E|\sigma_1n|$, giải thích vì sao không có $BR/\sqrt n$ với R cố định, và nêu cách sửa hợp lệ.`),
    application:b('One extreme feature can dominate a signed empirical sum, so the usual 1/√n rate needs a genuine uniform norm or moment premise.','Một feature cực đoan có thể chi phối tổng empirical có dấu, nên tốc độ 1/√n thông thường cần tiền đề chuẩn đều hoặc moment thực sự.'),
    formula:b(String.raw`The sample-dependent bound is $\widehat{\mathfrak R}_{abs}\le(B/n)\sqrt{\sum_i\|x_i\|^2}$. A uniform $\|x_i\|\le R$ gives $BR/\sqrt n$; if R grows with n, that rate changes.`,String.raw`Cận phụ thuộc mẫu là $\widehat{\mathfrak R}_{abs}\le(B/n)\sqrt{\sum_i\|x_i\|^2}$. Chặn đều $\|x_i\|\le R$ cho $BR/\sqrt n$; nếu R tăng theo n thì tốc độ đổi.`),
    steps:[b('Substitute the single nonzero feature into the signed linear supremum.','Thế feature khác không duy nhất vào supremum tuyến tính có dấu.'),b('Compare the exact value with the fixed-radius theorem’s missing premise.','So giá trị chính xác với tiền đề bán kính cố định đang thiếu.'),b('Repair via a justified uniform norm/moment condition, clipping with its target change, or the sample-dependent bound.','Sửa bằng điều kiện chuẩn/moment đều có biện minh, clipping có nêu thay đổi target, hoặc giữ cận phụ thuộc mẫu.')],
    primarySolution:[b(String.raw`Only $x_1$ is nonzero, with $\|x_1\|=n$, so the supremum is $B|\sigma_1n|/n$.`,String.raw`Chỉ $x_1$ khác không với $\|x_1\|=n$, nên supremum là $B|\sigma_1n|/n$.`),b(String.raw`Since $|\sigma_1|=1$, the expectation is $(B/n)n=B$.`,String.raw`Vì $|\sigma_1|=1$, kỳ vọng là $(B/n)n=B$.`),b('The sample violates any fixed feature radius R independent of n. Setting R=n would make BR/√n=B√n, a valid but loose worst-case bound, not a decaying rate.','Mẫu vi phạm mọi bán kính feature R cố định độc lập n. Đặt R=n cho BR/√n=B√n, là cận worst-case hợp lệ nhưng lỏng, không phải tốc độ giảm.'),b('Use a proved uniform norm or moment assumption, clip features while stating the modified target, or report the sample-dependent expression instead of claiming an unqualified 1/√n rate.','Dùng giả thiết chuẩn hoặc moment đều đã chứng minh, clip feature và nêu target đổi, hoặc báo biểu thức phụ thuộc mẫu thay vì khẳng định tốc độ 1/√n không điều kiện.')],
    companions:[
      {prompt:b(String.raw`For n=9, B=3 and one feature of norm 9 with all others zero, compute the exact sample-dependent complexity and the bound using R=9.`,String.raw`Với n=9, B=3, một feature chuẩn 9 và các feature khác bằng không, tính complexity phụ thuộc mẫu chính xác và cận dùng R=9.`),solution:[b(String.raw`The exact expression is $(B/n)E|\sigma_1n|=(3/9)(9)=3$.`,String.raw`Biểu thức chính xác là $(B/n)E|\sigma_1n|=(3/9)(9)=3$.`),b(String.raw`The uniform-radius bound is $BR/\sqrt n=3(9)/3=9$.`,String.raw`Cận bán kính đều là $BR/\sqrt n=3(9)/3=9$.`),b('The latter is valid but three times larger here; a fixed R independent of n was not supplied.','Cận sau hợp lệ nhưng lớn gấp ba ở đây; giả thiết R cố định độc lập n chưa có.') ]},
      {prompt:b(String.raw`For n=4, B=2 and one scalar feature equals 4 while the rest are zero. Calculate exact complexity and compare with the fixed-R upper bound.`,String.raw`Với n=4, B=2, một feature vô hướng bằng 4 còn lại bằng không. Tính complexity chính xác và so với cận bán kính cố định.`),solution:[b(String.raw`The signed numerator has absolute value $4$, so exact complexity is $(2/4)(4)=2$.`,String.raw`Tử có dấu có trị tuyệt đối $4$, nên complexity chính xác là $(2/4)(4)=2$.`),b(String.raw`Using the sample radius R=4 gives $BR/\sqrt n=2(4)/2=4$.`,String.raw`Dùng bán kính mẫu R=4 cho $BR/\sqrt n=2(4)/2=4$.`),b('This radius bound is a valid upper bound but cannot be described as a fixed-R rate across changing n.','Cận bán kính là cận trên hợp lệ nhưng không thể gọi là tốc độ R cố định khi n thay đổi.') ]},
      {prompt:b(String.raw`What additional premise would make $BR/\sqrt n$ a uniform rate for a sequence of samples, and what should be reported if no fixed bound exists?`,String.raw`Tiền đề bổ sung nào làm $BR/\sqrt n$ thành tốc độ đều cho dãy mẫu, và nên báo gì nếu không có cận cố định?`),solution:[b(String.raw`Require a uniform feature norm bound $\|x_i\|_2\le R$ with R independent of sample size, or a moment/tail condition that yields a justified substitute.`,String.raw`Yêu cầu chặn chuẩn feature đều $\|x_i\|_2\le R$ với R độc lập cỡ mẫu, hoặc điều kiện moment/đuôi cho thay thế có biện minh.`),b('Under that premise the squared-norm sum is at most nR², yielding BR/√n.','Dưới tiền đề đó tổng bình phương chuẩn không quá nR², cho BR/√n.'),b('Without it, report the sample-dependent bound B√(Σ||x_i||²)/n or state any clipping change explicitly.','Nếu thiếu, báo cận phụ thuộc mẫu B√(Σ||x_i||²)/n hoặc nêu rõ mọi thay đổi do clipping.') ]},
    ],
    reviewNote:'Checked the exact one-feature supremum, its dependence on n, and the distinction between sample-dependent and fixed-radius bounds.',sourceIds:['o-cmu705'],
  },
  'm2-w088-e1': {
    title:b('Find and verify the KKT multiplier','Tìm và kiểm tra multiplier KKT'),
    prompt:b(String.raw`Minimize $(w-4)^2$ subject to $w\le2$. Find the KKT multiplier $\lambda$ and explicitly minimize $L_\lambda(w)=(w-4)^2+\lambda(w-2)$. Verify the minimizer when $\lambda=4$.`,String.raw`Cực tiểu hóa $(w-4)^2$ với $w\le2$. Tìm multiplier KKT $\lambda$ và cực tiểu tường minh $L_\lambda(w)=(w-4)^2+\lambda(w-2)$. Kiểm tra nghiệm khi $\lambda=4$.`),
    application:b('A binding capacity limit moves the unconstrained target to the boundary; the multiplier measures the first-order force needed to enforce that limit.','Giới hạn công suất đang hoạt động đẩy mục tiêu không ràng buộc ra biên; multiplier đo lực bậc nhất cần để áp đặt giới hạn đó.'),
    formula:b(String.raw`For $g(w)=w-2\le0$, KKT requires feasibility, $\lambda\ge0$, $\lambda g(w^*)=0$, and $2(w^*-4)+\lambda=0$. Convexity makes these conditions sufficient here.`,String.raw`Với $g(w)=w-2\le0$, KKT cần tính khả thi, $\lambda\ge0$, $\lambda g(w^*)=0$ và $2(w^*-4)+\lambda=0$. Tính lồi làm các điều kiện này đủ ở đây.`),
    steps:[b('The unconstrained minimizer is 4, outside the feasible half-line, so the constrained minimizer is its boundary point 2.','Nghiệm không ràng buộc là 4, nằm ngoài nửa đường khả thi nên nghiệm ràng buộc là điểm biên 2.'),b('Use the active constraint and complementary slackness to set w*=2 and keep λ nonnegative.','Dùng ràng buộc hoạt động và bổ sung để đặt w*=2, đồng thời yêu cầu λ không âm.'),b('Solve stationarity and independently minimize the strictly convex Lagrangian to verify the same point.','Giải điều kiện dừng rồi cực tiểu hóa độc lập hàm Lagrange lồi nghiêm để kiểm tra cùng điểm đó.')],
    primarySolution:[b(String.raw`The feasible set is $(-\infty,2]$ and $(w-4)^2$ decreases up to 4, so its constrained minimizer is $w^*=2$.`,String.raw`Miền khả thi là $(-\infty,2]$ và $(w-4)^2$ giảm đến 4 nên nghiệm cực tiểu ràng buộc là $w^*=2$.`),b(String.raw`With $g(w)=w-2$, stationarity is $2(w^*-4)+\lambda=0$. Substitution gives $-4+\lambda=0$, hence $\lambda=4\ge0$; also $\lambda g(w^*)=0$.`,String.raw`Với $g(w)=w-2$, điều kiện dừng là $2(w^*-4)+\lambda=0$. Thế vào được $-4+\lambda=0$, nên $\lambda=4\ge0$; đồng thời $\lambda g(w^*)=0$.`),b(String.raw`At $\lambda=4$, $L'_4(w)=2(w-4)+4=2w-4$, whose unique zero is $w=2$, since $L''_4(w)=2>0$.`,String.raw`Khi $\lambda=4$, $L'_4(w)=2(w-4)+4=2w-4$, có nghiệm không duy nhất là $w=2$ vì $L''_4(w)=2>0$.`),b(String.raw`The Lagrangian value is $L_4(2)=4$. The minimizer verification uses strict convexity, not merely the stationarity equation.`,String.raw`Giá trị Lagrange là $L_4(2)=4$. Việc kiểm tra nghiệm dựa trên lồi nghiêm, không chỉ điều kiện dừng.`)],
    companions:[
      {prompt:b(String.raw`Minimize $(w-5)^2$ subject to $w\le1$. Find the active KKT multiplier and the minimum Lagrangian value.`,String.raw`Cực tiểu hóa $(w-5)^2$ với $w\le1$. Tìm multiplier KKT hoạt động và giá trị Lagrange nhỏ nhất.`),solution:[b(String.raw`The unconstrained target 5 exceeds the feasible cap, so $w^*=1$.`,String.raw`Mục tiêu không ràng buộc 5 vượt mức khả thi nên $w^*=1$.`),b(String.raw`Stationarity $2(1-5)+\lambda=0$ gives $\lambda=8\ge0$, and the constraint is active.`,String.raw`Điều kiện dừng $2(1-5)+\lambda=0$ cho $\lambda=8\ge0$, ràng buộc hoạt động.`),b(String.raw`Then $L_8(w)=(w-5)^2+8(w-1)$ has derivative $2w-2$ and positive second derivative 2, so its unique minimizer is 1 with value 16.`,String.raw`Khi đó $L_8(w)=(w-5)^2+8(w-1)$ có đạo hàm $2w-2$ và đạo hàm bậc hai 2 dương, nên nghiệm duy nhất là 1 với giá trị 16.`)]},
      {prompt:b(String.raw`Minimize $(w+2)^2$ subject to $w\le0$. Determine whether the inequality binds and find its multiplier.`,String.raw`Cực tiểu hóa $(w+2)^2$ với $w\le0$. Xác định bất đẳng thức có hoạt động không và tìm multiplier.`),solution:[b(String.raw`The unconstrained minimizer $w=-2$ is feasible, so it remains the constrained minimizer.`,String.raw`Nghiệm không ràng buộc $w=-2$ khả thi nên cũng là nghiệm ràng buộc.`),b(String.raw`The inequality is slack: $g(-2)=-2<0$. Complementary slackness gives $\lambda=0$.`,String.raw`Bất đẳng thức không chặt: $g(-2)=-2<0$. Điều kiện bổ sung cho $\lambda=0$.`),b(String.raw`Stationarity $2(-2+2)+0=0$ holds, and convexity confirms global optimality.`,String.raw`Điều kiện dừng $2(-2+2)+0=0$ đúng, tính lồi xác nhận tối ưu toàn cục.`)]},
      {prompt:b(String.raw`For $f(w)=(w-3)^2$ and $w\le1$, verify $\lambda=4$ by differentiating the Lagrangian and evaluating its minimum value.`,String.raw`Với $f(w)=(w-3)^2$ và $w\le1$, hãy kiểm tra $\lambda=4$ bằng cách lấy đạo hàm Lagrange và tính giá trị cực tiểu.`),solution:[b(String.raw`The constraint forces $w^*=1$ because the unconstrained minimizer 3 is infeasible.`,String.raw`Ràng buộc buộc $w^*=1$ vì nghiệm không ràng buộc 3 không khả thi.`),b(String.raw`For $L_4=(w-3)^2+4(w-1)$, the derivative is $2(w-3)+4=2w-2$, so its zero is 1 and $L_4''=2>0$.`,String.raw`Với $L_4=(w-3)^2+4(w-1)$, đạo hàm là $2(w-3)+4=2w-2$, nên nghiệm là 1 và $L_4''=2>0$.`),b(String.raw`Thus the unique minimum occurs at $w=1$ and equals $L_4(1)=4$.`,String.raw`Do đó cực tiểu duy nhất tại $w=1$ và bằng $L_4(1)=4$.`)]},
    ],
    reviewNote:'Checked feasible boundary versus slack cases, multiplier sign and complementarity, and strict-convex Lagrangian minimization.',sourceIds:['o-boyd'],
  },
  'm2-w088-e2': {
    title:b('Prove stationarity gives a global penalized minimum','Chứng minh điều kiện dừng cho cực tiểu toàn cục có phạt'),
    prompt:b(String.raw`For convex functions $L$ and $\Omega$ with $\lambda\ge0$, prove that $0\in\partial L(x^*)+\lambda\partial\Omega(x^*)$ implies that $x^*$ globally minimizes $L+\lambda\Omega$.`,String.raw`Với hàm lồi $L$ và $\Omega$ cùng $\lambda\ge0$, hãy chứng minh $0\in\partial L(x^*)+\lambda\partial\Omega(x^*)$ suy ra $x^*$ cực tiểu toàn cục $L+\lambda\Omega$.`),
    application:b('A first-order certificate for a convex fit and penalty is useful even when the minimizer cannot be written in closed form.','Chứng nhận bậc nhất cho loss lồi có phạt hữu ích ngay cả khi không thể viết nghiệm tối ưu dạng đóng.'),
    formula:b(String.raw`If $g\in\partial L(x^*)$, $h\in\partial\Omega(x^*)$, and $g+\lambda h=0$, then $L(x)\ge L(x^*)+g^T(x-x^*)$ and $\Omega(x)\ge\Omega(x^*)+h^T(x-x^*)$; add the inequalities.`,String.raw`Nếu $g\in\partial L(x^*)$, $h\in\partial\Omega(x^*)$ và $g+\lambda h=0$, thì $L(x)\ge L(x^*)+g^T(x-x^*)$ và $\Omega(x)\ge\Omega(x^*)+h^T(x-x^*)$; cộng hai bất đẳng thức.`),
    steps:[b('Unpack the subgradient-sum inclusion by choosing subgradients whose weighted sum is zero.','Khai triển inclusion tổng subgradient bằng cách chọn các subgradient có tổng có trọng số bằng không.'),b('Write the supporting-hyperplane inequality for each convex function at x*.','Viết bất đẳng thức siêu phẳng đỡ cho từng hàm lồi tại x*.'),b('Add the inequalities; stationarity cancels the linear terms and leaves global objective dominance.','Cộng các bất đẳng thức; điều kiện dừng triệt các hạng tuyến tính và còn lại tính trội toàn cục của mục tiêu.')],
    primarySolution:[b(String.raw`The inclusion means there exist $g\in\partial L(x^*)$ and $h\in\partial\Omega(x^*)$ such that $g+\lambda h=0$.`,String.raw`Inclusion nghĩa là có $g\in\partial L(x^*)$ và $h\in\partial\Omega(x^*)$ sao cho $g+\lambda h=0$.`),b(String.raw`Convexity gives $L(x)\ge L(x^*)+g^T(x-x^*)$ and $\Omega(x)\ge\Omega(x^*)+h^T(x-x^*)$ for every x.`,String.raw`Tính lồi cho $L(x)\ge L(x^*)+g^T(x-x^*)$ và $\Omega(x)\ge\Omega(x^*)+h^T(x-x^*)$ với mọi x.`),b(String.raw`Multiply the second inequality by $\lambda\ge0$ and add. The extra term is $(g+\lambda h)^T(x-x^*)=0$, so $L(x)+\lambda\Omega(x)\ge L(x^*)+lambdaOmega(x^*)$.`,String.raw`Nhân bất đẳng thức thứ hai với $\lambda\ge0$ rồi cộng. Hạng phụ là $(g+\lambda h)^T(x-x^*)=0$, nên $L(x)+\lambda\Omega(x)\ge L(x^*)+lambdaOmega(x^*)$.`),b('This proves global minimality; uniqueness would require additional strict convexity and is not implied by the certificate alone.','Điều này chứng minh cực tiểu toàn cục; tính duy nhất cần thêm lồi nghiêm và không suy ra chỉ từ chứng nhận này.')],
    companions:[
      {prompt:b(String.raw`Let $L(x)=(x-2)^2$ and $\Omega(x)=x^2$ at $x^*=1$ with $\lambda=1$. Verify the subgradient condition and global minimum.`,String.raw`Cho $L(x)=(x-2)^2$, $\Omega(x)=x^2$, $x^*=1$ và $\lambda=1$. Kiểm tra điều kiện subgradient và cực tiểu toàn cục.`),solution:[b(String.raw`Both functions are differentiable, with $L'(1)=2(1-2)=-2$ and $\Omega'(1)=2$.`,String.raw`Hai hàm khả vi, với $L'(1)=2(1-2)=-2$ và $\Omega'(1)=2$.`),b(String.raw`Their sum is $-2+1(2)=0$, so stationarity holds.`,String.raw`Tổng có trọng số là $-2+1(2)=0$, nên điều kiện dừng đúng.`),b(String.raw`The penalized objective is $(x-2)^2+x^2=2x^2-4x+4$, minimized at $x=1$ by completing the square; its value is 2.`,String.raw`Mục tiêu có phạt là $(x-2)^2+x^2=2x^2-4x+4$, đạt cực tiểu tại $x=1$ khi hoàn thành bình phương; giá trị bằng 2.`)]},
      {prompt:b(String.raw`For $L(x)=|x-1|$ and $\Omega(x)=|x|$, test the certificate at $x^*=0$ with $\lambda=1$ and state the global minimizers.`,String.raw`Với $L(x)=|x-1|$, $\Omega(x)=|x|$, kiểm tra chứng nhận tại $x^*=0$, $\lambda=1$ và nêu các nghiệm cực tiểu toàn cục.`),solution:[b(String.raw`At zero, $\partial L(0)={-1}$ and $\partial\Omega(0)=[-1,1]$.`,String.raw`Tại không, $\partial L(0)={-1}$ và $\partial\Omega(0)=[-1,1]$.`),b(String.raw`Choose $g=-1$ and $h=1$, giving $g+\lambda h=0$.`,String.raw`Chọn $g=-1$, $h=1$ thì $g+\lambda h=0$.`),b(String.raw`Therefore zero globally minimizes $|x-1|+|x|$. In fact every $x\in[0,1]$ gives value 1, so stationarity need not imply uniqueness.`,String.raw`Vì vậy không là nghiệm cực tiểu toàn cục của $|x-1|+|x|$. Thực tế mọi $x\in[0,1]$ cho giá trị 1, nên điều kiện dừng không nhất thiết suy tính duy nhất.`)]},
      {prompt:b(String.raw`Suppose $g+\lambda h=0$ and $\lambda>0$, but $\lambda$ were negative instead. Which step in the convex subgradient proof would fail?`,String.raw`Giả sử $g+\lambda h=0$ và $\lambda>0$, nhưng nếu $\lambda$ âm thì bước nào trong chứng minh subgradient lồi sẽ hỏng?`),solution:[b('The subgradient inequality for Ω is a lower bound on Ω(x)−Ω(x*).','Bất đẳng thức subgradient của Ω là cận dưới cho Ω(x)−Ω(x*).'),b(String.raw`Multiplying a lower bound by a negative $\lambda$ reverses its inequality direction, so it no longer provides the required lower bound on $\lambda\Omega(x)$.`,String.raw`Nhân cận dưới với $\lambda$ âm đảo chiều bất đẳng thức nên không còn cận dưới cần thiết cho $\lambda\Omega(x)$.`),b('Thus $\lambda\ge0$ is essential for this sufficient-condition argument; a negative-weight sum need not be convex.','Vì vậy $\lambda\ge0$ thiết yếu cho lập luận điều kiện đủ; tổng có trọng số âm không nhất thiết lồi.') ]},
    ],
    reviewNote:'Checked subgradient-sum interpretation, sign of the multiplier when scaling an inequality, globality, and the possible nonuniqueness boundary.',sourceIds:['o-boyd'],
  },
  'm2-w088-e3': {
    title:b('Separate approximation, estimation, and optimization error','Tách sai số xấp xỉ, ước lượng và tối ưu'),
    prompt:b(String.raw`Let $\mathcal F$ be finite and $\mathcal G\supseteq\mathcal F$ a stated reference class. Define $f^*=\arg\min_{f\in\mathcal F}J(f)$, $\widehat f=\arg\min_{f\in\mathcal F}\widehat J(f)$, and $\widehat J(\widetilde f)\le\widehat J(\widehat f)+\varepsilon_{\rm opt}$. Decompose $J(\widetilde f)-\inf_{g\in\mathcal G}J(g)$ into approximation, in-class estimation, and returned-iterate terms; then prove $J(\widetilde f)-J(f^*)\le2\sup_{f\in\mathcal F}|R(f)-\widehat R(f)|+\varepsilon_{\rm opt}$.`,String.raw`Cho $\mathcal F$ hữu hạn và $\mathcal G\supseteq\mathcal F$ là lớp tham chiếu được nêu rõ. Đặt $f^*=\arg\min_{f\in\mathcal F}J(f)$, $\widehat f=\arg\min_{f\in\mathcal F}\widehat J(f)$ và $\widehat J(\widetilde f)\le\widehat J(\widehat f)+\varepsilon_{\rm opt}$. Phân rã $J(\widetilde f)-\inf_{g\in\mathcal G}J(g)$ thành các hạng xấp xỉ, ước lượng trong lớp và iterate trả về; rồi chứng minh $J(\widetilde f)-J(f^*)\le2\sup_{f\in\mathcal F}|R(f)-\widehat R(f)|+\varepsilon_{\rm opt}$.`),
    application:b('A fitted model may miss the best attainable reference, suffer sampling error, and stop before empirical optimization is exact; these are distinct terms.','Mô hình khớp có thể không đạt tham chiếu tốt nhất, chịu sai số lấy mẫu và dừng trước khi tối ưu thực nghiệm chính xác; đây là các hạng khác nhau.'),
    formula:b(String.raw`For a larger reference class $\mathcal G\supseteq\mathcal F$, $J(\widetilde f)-\inf_{\mathcal G}J=[J(f^*)-\inf_{\mathcal G}J]+[J(\widehat f)-J(f^*)]+[J(\widetilde f)-J(\widehat f)]$. If $\Delta=\sup_{\mathcal F}|R-\widehat R|$, the in-class excess is at most $2\Delta+\varepsilon_{\mathrm{opt}}$.`,String.raw`Với lớp tham chiếu lớn hơn $\mathcal G\supseteq\mathcal F$, $J(\widetilde f)-\inf_{\mathcal G}J=[J(f^*)-\inf_{\mathcal G}J]+[J(\widehat f)-J(f^*)]+[J(\widetilde f)-J(\widehat f)]$. Nếu $\Delta=\sup_{\mathcal F}|R-\widehat R|$, excess trong lớp không quá $2\Delta+\varepsilon_{\mathrm{opt}}$.`),
    steps:[b('Insert the exact minimizer f* and empirical minimizer f-hat to obtain approximation, estimation, and iterate terms.','Chèn nghiệm chính xác f* và nghiệm thực nghiệm f-hat để có hạng xấp xỉ, ước lượng và iterate.'),b('The first term compares F with the explicitly stated larger reference; it vanishes if the reference is F itself.','Hạng đầu so F với lớp tham chiếu lớn đã nêu; nó bằng không nếu tham chiếu chính là F.'),b('For the in-class bound, move from population to empirical objective at the returned point, use ε-optimality and empirical minimization, then return to population objective.','Để chặn trong lớp, chuyển từ mục tiêu quần thể sang thực nghiệm tại điểm trả về, dùng ε-tối ưu và cực tiểu thực nghiệm rồi quay lại mục tiêu quần thể.')],
    primarySolution:[b(String.raw`Let $J^*_{\mathcal G}=\inf_{g\in\mathcal G}J(g)$ for a named reference class $\mathcal G\supseteq\mathcal F$. Adding and subtracting $J(f^*)$ and $J(\widehat f)$ gives $J(\widetilde f)-J^*_{\mathcal G}=[J(f^*)-J^*_{\mathcal G}]+[J(\widehat f)-J(f^*)]+[J(\widetilde f)-J(\widehat f)]$.`,String.raw`Gọi $J^*_{\mathcal G}=\inf_{g\in\mathcal G}J(g)$ với lớp tham chiếu $\mathcal G\supseteq\mathcal F$ được nêu rõ. Thêm bớt $J(f^*)$ và $J(\widehat f)$ được $J(\widetilde f)-J^*_{\mathcal G}=[J(f^*)-J^*_{\mathcal G}]+[J(\widehat f)-J(f^*)]+[J(\widetilde f)-J(\widehat f)]$.`),b('The first is class approximation, the second is in-class estimation, and the signed third is the returned-iterate difference. If G=F, the approximation term is zero.','Hạng đầu là xấp xỉ lớp, hạng hai là ước lượng trong lớp, hạng ba có dấu là chênh lệch iterate trả về. Nếu G=F, hạng xấp xỉ bằng không.'),b(String.raw`Set $\Delta=\sup_{f\in\mathcal F}|R(f)-\widehat R(f)|=\sup_{\mathcal F}|J-\widehat J|$, since the same penalty cancels. Then $J(\widetilde f)\le\widehat J(\widetilde f)+\Delta\le\widehat J(\widehat f)+\varepsilon_{\mathrm{opt}}+\Delta$.`,String.raw`Đặt $\Delta=\sup_{f\in\mathcal F}|R(f)-\widehat R(f)|=\sup_{\mathcal F}|J-\widehat J|$ vì penalty như nhau triệt tiêu. Khi đó $J(\widetilde f)\le\widehat J(\widetilde f)+\Delta\le\widehat J(\widehat f)+\varepsilon_{\mathrm{opt}}+\Delta$.`),b(String.raw`Empirical optimality gives $\widehat J(\widehat f)\le\widehat J(f^*)\le J(f^*)+\Delta$. Hence $J(\widetilde f)-J(f^*)\le2\Delta+\varepsilon_{\mathrm{opt}}$.`,String.raw`Tối ưu thực nghiệm cho $\widehat J(\widehat f)\le\widehat J(f^*)\le J(f^*)+\Delta$. Suy ra $J(\widetilde f)-J(f^*)\le2\Delta+\varepsilon_{\mathrm{opt}}$.`)],
    companions:[
      {prompt:b(String.raw`On $\mathcal F$, suppose $\Delta=0.04$ and the returned iterate has empirical optimization tolerance $\varepsilon_{\mathrm{opt}}=0.01$. Find the in-class population-objective excess certificate.`,String.raw`Trên $\mathcal F$, cho $\Delta=0.04$ và iterate trả về có dung sai tối ưu thực nghiệm $\varepsilon_{\mathrm{opt}}=0.01$. Tìm chứng nhận excess mục tiêu quần thể trong lớp.`),solution:[b(String.raw`The two population-to-empirical endpoint deviations contribute $2\Delta=2(0.04)=0.08$.`,String.raw`Hai sai lệch đầu mút quần thể-thực nghiệm đóng góp $2\Delta=2(0.04)=0.08$.`),b(String.raw`Add the optimization allowance $0.01$, giving $0.08+0.01=0.09$.`,String.raw`Cộng dung sai tối ưu $0.01$, được $0.08+0.01=0.09$.`),b('This certifies comparison with the best member of F; it does not remove any approximation gap to a larger reference class.','Điều này chứng nhận so sánh với phần tử tốt nhất của F; nó không xóa khoảng cách xấp xỉ tới lớp tham chiếu lớn hơn.') ]},
      {prompt:b(String.raw`Let the best in-class objective be 3, the larger-reference infimum be 2.4, $\Delta=0.05$, and $\varepsilon_{\mathrm{opt}}=0.02$. Give the three-term certificate to the larger reference.`,String.raw`Cho mục tiêu tốt nhất trong lớp là 3, infimum lớp tham chiếu lớn là 2.4, $\Delta=0.05$ và $\varepsilon_{\mathrm{opt}}=0.02$. Hãy nêu chứng nhận ba hạng so với tham chiếu lớn.`),solution:[b(String.raw`The approximation term is $3-2.4=0.6$.`,String.raw`Hạng xấp xỉ là $3-2.4=0.6$.`),b(String.raw`The estimation-plus-optimization term is at most $2(0.05)+0.02=0.12$.`,String.raw`Hạng ước lượng cộng tối ưu không quá $2(0.05)+0.02=0.12$.`),b(String.raw`Adding gives at most $0.6+0.12=0.72$ above the larger-reference infimum.`,String.raw`Cộng lại cho cận không quá $0.6+0.12=0.72$ so với infimum tham chiếu lớn.`)]},
      {prompt:b(String.raw`If $\lambda=2$ and the same penalty $\Omega$ is used in $J=R+lambdaOmega$ and $\widehat J=\widehat R+lambdaOmega$, show why the uniform deviation depends only on $R-\widehat R$.`,String.raw`Nếu $\lambda=2$ và cùng penalty $\Omega$ xuất hiện trong $J=R+lambdaOmega$, $\widehat J=\widehat R+lambdaOmega$, hãy chỉ ra vì sao độ lệch đều chỉ phụ thuộc $R-\widehat R$.`),solution:[b(String.raw`Subtract objectives at a fixed f: $J(f)-\widehat J(f)=R(f)+2\Omega(f)-[\widehat R(f)+2\Omega(f)]$.`,String.raw`Trừ hai mục tiêu tại f cố định: $J(f)-\widehat J(f)=R(f)+2\Omega(f)-[\widehat R(f)+2\Omega(f)]$.`),b(String.raw`The identical penalty terms cancel exactly, leaving $R(f)-\widehat R(f)$.`,String.raw`Hai hạng penalty giống nhau triệt tiêu chính xác, còn $R(f)-\widehat R(f)$.`),b(String.raw`Taking the supremum of absolute values therefore gives $\sup_{\mathcal F}|J-\widehat J|=\sup_{\mathcal F}|R-\widehat R|$; if penalties differ, this equality need not hold.`,String.raw`Do đó lấy supremum trị tuyệt đối cho $\sup_{\mathcal F}|J-\widehat J|=\sup_{\mathcal F}|R-\widehat R|$; nếu penalty khác nhau thì đẳng thức này có thể sai.`)]},
    ],
    reviewNote:'Checked the reference-class decomposition, nonnegative first terms, signed iterate term, penalty cancellation, and both endpoints of the uniform-deviation bound.',sourceIds:['o-cmu705','o-boyd'],
  },
  'm2-w088-e4': {
    title:b('Protect an untouched final test set','Bảo vệ tập test cuối chưa dùng'),
    prompt:b(String.raw`You try 80 $\lambda$ values and report the best test loss. Redesign evaluation.`,String.raw`Bạn thử 80 giá trị $\lambda$ rồi báo test loss tốt nhất. Hãy thiết kế lại đánh giá.`),
    application:b('Repeatedly choosing hyperparameters by test performance turns the reported test result into another selection criterion.','Chọn siêu tham số lặp lại theo hiệu năng test khiến kết quả test được báo cáo trở thành một tiêu chí tuyển chọn nữa.'),
    formula:b('Tune only on training and validation data; freeze the entire pipeline before one evaluation on an untouched time-ordered holdout, or use nested rolling-origin validation.','Chỉ tinh chỉnh bằng dữ liệu huấn luyện và validation; đóng băng toàn bộ quy trình trước một lần đánh giá trên holdout theo thời gian chưa dùng, hoặc dùng validation rolling-origin lồng.'),
    steps:[b('Recognize that choosing the smallest of 80 test losses selects for favorable test noise.','Nhận ra chọn nhỏ nhất trong 80 test loss là chọn theo nhiễu test thuận lợi.'),b('Move hyperparameter selection to training/validation folds that respect chronological order and dependence.','Chuyển việc chọn siêu tham số sang các fold train/validation tôn trọng thứ tự thời gian và phụ thuộc.'),b('Freeze λ, preprocessing, and model selection rules; evaluate once on a future holdout and report uncertainty for the time-series regime.','Đóng băng λ, tiền xử lý và quy tắc chọn mô hình; đánh giá một lần trên holdout tương lai và báo bất định phù hợp chế độ chuỗi thời gian.')],
    primarySolution:[b('The minimum among 80 test losses is optimistically selected; it is not an unbiased final performance estimate.','Giá trị nhỏ nhất trong 80 test loss được chọn lạc quan; nó không phải ước lượng hiệu năng cuối không chệch.'),b('Use chronological validation or nested rolling-origin splits to choose λ, with all preprocessing fitted inside each training fold.','Dùng validation theo thời gian hoặc chia rolling-origin lồng để chọn λ, và khớp mọi tiền xử lý bên trong từng fold huấn luyện.'),b('After the choices are frozen, score the selected procedure once on an untouched later holdout.','Sau khi đóng băng lựa chọn, chấm quy trình đã chọn đúng một lần trên holdout muộn hơn chưa dùng.'),b('For serial data, quantify uncertainty with a dependence-aware method justified for the evaluation horizon; repeated access to the holdout would recreate selection leakage.','Với dữ liệu chuỗi, lượng hóa bất định bằng phương pháp xét phụ thuộc có biện minh cho chân trời đánh giá; truy cập holdout lặp lại sẽ tạo lại rò rỉ chọn lọc.')],
    companions:[
      {prompt:b(String.raw`A researcher chooses one of 30 regularizers using validation loss, then reports that same validation minimum as final test performance. What is the defect and repair?`,String.raw`Nhà nghiên cứu chọn một trong 30 regularizer bằng validation loss rồi báo minimum validation đó là hiệu năng test cuối. Sai ở đâu và sửa thế nào?`),solution:[b('Validation has been used both for selection and final reporting, so the minimum is selection-optimistic.','Validation vừa dùng để chọn vừa dùng báo cáo cuối nên giá trị nhỏ nhất bị lạc quan do chọn.'),b('Keep selection on training/validation data but reserve an independent final test set.','Giữ lựa chọn trên train/validation nhưng dành riêng tập test cuối độc lập.'),b('Freeze the selected model and scoring pipeline before evaluating the reserved test set once.','Đóng băng mô hình và quy trình chấm đã chọn trước khi đánh giá tập test dự trữ một lần.') ]},
      {prompt:b(String.raw`For a forecasting series, compare a random validation split with rolling-origin validation for choosing a regularization parameter.`,String.raw`Với chuỗi dự báo, hãy so sánh chia validation ngẫu nhiên với validation rolling-origin khi chọn tham số regularization.`),solution:[b('A random split may train on observations later than a validation date, violating forecast-time information order.','Chia ngẫu nhiên có thể huấn luyện bằng quan sát muộn hơn ngày validation, vi phạm thứ tự thông tin dự báo.'),b('Rolling-origin folds train only on the past and validate on a subsequent block, matching the intended deployment direction.','Fold rolling-origin chỉ huấn luyện bằng quá khứ rồi validation trên khối tiếp theo, khớp chiều triển khai dự kiến.'),b('Choose the parameter across these folds, freeze it, and use a separate final future block for one performance report.','Chọn tham số qua các fold này, đóng băng rồi dùng khối tương lai cuối riêng cho một báo cáo hiệu năng.') ]},
      {prompt:b(String.raw`After freezing all choices, an analyst evaluates once on a 100-date holdout with strong serial dependence. Why may an IID standard error still be invalid?`,String.raw`Sau khi đóng băng mọi lựa chọn, nhà phân tích đánh giá một lần trên holdout 100 ngày có phụ thuộc chuỗi mạnh. Vì sao sai số chuẩn IID vẫn có thể không hợp lệ?`),solution:[b('A single holdout prevents repeated selection but does not make its serial observations independent.','Một holdout duy nhất ngăn chọn lặp nhưng không làm các quan sát chuỗi độc lập.'),b('An IID standard error omits covariance terms that affect the variance of the average loss difference.','Sai số chuẩn IID bỏ các hạng covariance ảnh hưởng phương sai trung bình chênh lệch loss.'),b('Use a dependence-aware uncertainty procedure with conditions and block scale suited to the process and horizon; the point estimate can still be reported descriptively.','Dùng thủ tục bất định xét phụ thuộc với điều kiện và block phù hợp quá trình, chân trời; vẫn có thể báo ước lượng điểm như mô tả.') ]},
    ],
    reviewNote:'Checked selection leakage, chronology of each split, fold-local preprocessing, and the remaining dependence issue after one untouched evaluation.',sourceIds:['o-cmu705'],
  },
  'm2-w088-e5': {
    title:b('A penalty can raise target risk','Penalty có thể làm tăng target risk'),
    prompt:b(String.raw`For $R(w)=(w-10)^2$ and penalty $\lambda w^2$, find $w_\lambda$ and show the target risk rises.`,String.raw`Với $R(w)=(w-10)^2$ và penalty $\lambda w^2$, tìm $w_\lambda$ và chứng minh target risk tăng.`),
    application:b('Regularization trades fidelity to a target against a chosen penalty; the penalized objective can improve while unpenalized target risk worsens.','Regularization đánh đổi độ khớp target với penalty đã chọn; objective có phạt có thể tốt hơn trong khi target risk không phạt xấu đi.'),
    formula:b(String.raw`For $\lambda\ge0$, minimize $J_\lambda(w)=(w-10)^2+\lambda w^2$. Then $w_\lambda=10/(1+\lambda)$ and $R(w_\lambda)=[10\lambda/(1+\lambda)]^2$.`,String.raw`Với $\lambda\ge0$, cực tiểu hóa $J_\lambda(w)=(w-10)^2+\lambda w^2$. Khi đó $w_\lambda=10/(1+\lambda)$ và $R(w_\lambda)=[10\lambda/(1+\lambda)]^2$.`),
    steps:[b('Differentiate the strictly convex penalized quadratic and solve its first-order equation.','Lấy đạo hàm quadratic có phạt lồi nghiêm rồi giải phương trình bậc nhất.'),b('Substitute the optimizer into the target risk without the penalty.','Thế nghiệm vào target risk không có penalty.'),b('Differentiate with respect to λ or compare values to establish monotone increase for λ≥0, including the λ=0 boundary.','Lấy đạo hàm theo λ hoặc so giá trị để chứng minh tăng đơn điệu khi λ≥0, kể cả biên λ=0.')],
    primarySolution:[b(String.raw`The derivative is $J'_\lambda(w)=2(w-10)+2\lambda w$, and $J''_\lambda(w)=2(1+\lambda)>0$ for $\lambda\ge0$.`,String.raw`Đạo hàm là $J'_\lambda(w)=2(w-10)+2\lambda w$, còn $J''_\lambda(w)=2(1+\lambda)>0$ khi $\lambda\ge0$.`),b(String.raw`Setting the derivative to zero gives $(1+\lambda)w=10$, so the unique optimizer is $w_\lambda=10/(1+\lambda)$.`,String.raw`Đặt đạo hàm bằng không cho $(1+\lambda)w=10$, nên nghiệm duy nhất là $w_\lambda=10/(1+\lambda)$.`),b(String.raw`The target error is $w_\lambda-10=-10\lambda/(1+\lambda)$, hence $R(w_\lambda)=[10\lambda/(1+\lambda)]^2$.`,String.raw`Sai số target là $w_\lambda-10=-10\lambda/(1+\lambda)$, nên $R(w_\lambda)=[10\lambda/(1+\lambda)]^2$.`),b(String.raw`For $\lambda\ge0$, $\lambda/(1+\lambda)$ increases from 0 toward 1, so the target risk rises from 0 toward 100; at λ=0 the penalty has no effect.`,String.raw`Khi $\lambda\ge0$, $\lambda/(1+\lambda)$ tăng từ 0 về 1 nên target risk tăng từ 0 về 100; tại λ=0 penalty chưa ảnh hưởng.`)],
    companions:[
      {prompt:b(String.raw`For target $R(w)=(w-6)^2$ and penalty $3w^2$, find the optimizer and its unpenalized target risk.`,String.raw`Với target $R(w)=(w-6)^2$ và penalty $3w^2$, tìm nghiệm tối ưu và target risk không phạt.`),solution:[b(String.raw`The penalized derivative is $2(w-6)+6w=8w-12$.`,String.raw`Đạo hàm có phạt là $2(w-6)+6w=8w-12$.`),b(String.raw`Setting it to zero yields $w=12/8=1.5$, with positive second derivative 8.`,String.raw`Đặt bằng không cho $w=12/8=1.5$, với đạo hàm bậc hai 8 dương.`),b(String.raw`The target risk is $(1.5-6)^2=(-4.5)^2=20.25$, compared with zero at the unpenalized target w=6.`,String.raw`Target risk là $(1.5-6)^2=(-4.5)^2=20.25$, so với mức không tại target không phạt w=6.`)]},
      {prompt:b(String.raw`Minimize $(w-8)^2+7w^2$. Compute $w_\lambda$ and verify strict convexity.`,String.raw`Cực tiểu hóa $(w-8)^2+7w^2$. Tính $w_\lambda$ và kiểm tra lồi nghiêm.`),solution:[b(String.raw`Differentiate to obtain $2(w-8)+14w=16w-16$.`,String.raw`Lấy đạo hàm được $2(w-8)+14w=16w-16$.`),b(String.raw`The zero is $w=1$; the second derivative is $16>0$, so it is the unique global minimizer.`,String.raw`Nghiệm đạo hàm bằng không là $w=1$; đạo hàm bậc hai là $16>0$ nên đây là cực tiểu toàn cục duy nhất.`),b(String.raw`The target risk for target 8 is $(1-8)^2=49$, while at zero penalty the target risk would be 0.`,String.raw`Target risk với target 8 là $(1-8)^2=49$, còn khi penalty bằng không thì target risk là 0.`)]},
      {prompt:b(String.raw`For target $a>0$, penalty $\lambda w^2$, and $\lambda\ge0$, derive the optimizer and its target risk; identify the limit as $\lambda\to\infty$.`,String.raw`Với target $a>0$, penalty $\lambda w^2$ và $\lambda\ge0$, hãy suy nghiệm tối ưu, target risk và giới hạn khi $\lambda\to\infty$.`),solution:[b(String.raw`Minimize $(w-a)^2+\lambda w^2$; stationarity $2(w-a)+2\lambda w=0$ gives $w_\lambda=a/(1+\lambda)$.`,String.raw`Cực tiểu hóa $(w-a)^2+\lambda w^2$; điều kiện dừng $2(w-a)+2\lambda w=0$ cho $w_\lambda=a/(1+\lambda)$.`),b(String.raw`Then $R(w_\lambda)=(a/(1+\lambda)-a)^2=[a\lambda/(1+\lambda)]^2$.`,String.raw`Khi đó $R(w_\lambda)=(a/(1+\lambda)-a)^2=[a\lambda/(1+\lambda)]^2$.`),b(String.raw`As $\lambda\to\infty$, the fitted weight tends to 0 and target risk tends to $a^2$; at $\lambda=0$ risk is 0.`,String.raw`Khi $\lambda\to\infty$, trọng số khớp tiến về 0 và target risk tiến về $a^2$; tại $\lambda=0$ risk bằng 0.`)]},
    ],
    reviewNote:'Checked the unique quadratic minimizer for λ≥0, target-risk substitution, monotonicity including λ=0, and the large-penalty limit.',sourceIds:['o-boyd'],
  },
  'm2-w089-e1': {
    title:b('Compute the OGD static-regret certificate','Tính chứng nhận static regret của OGD'),
    prompt:b(String.raw`For diameter $D=1$, gradient bound $G=2$, and horizon $T=25$, find the optimized step size $\eta$ and regret bound.`,String.raw`Với đường kính $D=1$, cận gradient $G=2$ và chân trời $T=25$, tìm bước $\eta$ tối ưu và cận regret.`),
    application:b('A regret certificate chooses a step size to balance the initial-distance cost against accumulated gradient noise.','Chứng nhận regret chọn bước để cân bằng chi phí khoảng cách ban đầu với gradient tích lũy.'),
    formula:b(String.raw`For projected OGD on a closed convex set of diameter $D$ with $|g_t|\le G$, $\operatorname{Reg}_T(u)\le D^2/(2\eta)+\eta G^2T/2$. The minimizing $\eta=D/(G\sqrt T)$ yields $DG\sqrt T$.`,String.raw`Với OGD chiếu trên tập đóng lồi đường kính $D$, $|g_t|\le G$, ta có $\operatorname{Reg}_T(u)\le D^2/(2\eta)+\eta G^2T/2$. Bước tối ưu $\eta=D/(G\sqrt T)$ cho $DG\sqrt T$.`),
    steps:[b('Substitute D, G, and T into the minimizing step-size expression.','Thế D, G, T vào biểu thức bước tối ưu.'),b('Evaluate each of the two regret terms at that step size.','Tính từng hạng trong hai hạng regret tại bước đó.'),b('Add the terms and interpret the result as a worst-case comparator certificate, not realized profit.','Cộng hai hạng và hiểu kết quả là chứng nhận so sánh worst-case, không phải lợi nhuận thực tế.')],
    primarySolution:[b(String.raw`The optimized step is $\eta=D/(G\sqrt T)=1/(2\cdot5)=0.1$.`,String.raw`Bước tối ưu là $\eta=D/(G\sqrt T)=1/(2\cdot5)=0.1$.`),b(String.raw`The distance term is $D^2/(2\eta)=1/(0.2)=5$.`,String.raw`Hạng khoảng cách là $D^2/(2\eta)=1/(0.2)=5$.`),b(String.raw`The gradient term is $\eta G^2T/2=0.1(4)(25)/2=5$.`,String.raw`Hạng gradient là $\eta G^2T/2=0.1(4)(25)/2=5$.`),b(String.raw`Their sum is 10, equal to $DG\sqrt T=1(2)(5)=10$. This is a bound on regret relative to each fixed comparator in the feasible set.`,String.raw`Tổng bằng 10, đúng bằng $DG\sqrt T=1(2)(5)=10$. Đây là cận regret so với từng comparator cố định trong tập khả thi.`)],
    companions:[
      {prompt:b(String.raw`For $D=2$, $G=1$, and $T=16$, calculate the optimized step and both terms in the regret bound.`,String.raw`Với $D=2$, $G=1$, $T=16$, hãy tính bước tối ưu và hai hạng của cận regret.`),solution:[b(String.raw`The step is $\eta=D/(G\sqrt T)=2/4=0.5$.`,String.raw`Bước là $\eta=D/(G\sqrt T)=2/4=0.5$.`),b(String.raw`The distance term is $D^2/(2\eta)=4/1=4$.`,String.raw`Hạng khoảng cách là $D^2/(2\eta)=4/1=4$.`),b(String.raw`The gradient term is $\eta G^2T/2=0.5(1)(16)/2=4$, so the total is 8.`,String.raw`Hạng gradient là $\eta G^2T/2=0.5(1)(16)/2=4$, nên tổng bằng 8.`)]},
      {prompt:b(String.raw`For $D=3$, $G=2$, and $T=9$, find the optimized step and the regret certificate.`,String.raw`Với $D=3$, $G=2$, $T=9$, hãy tìm bước tối ưu và chứng nhận regret.`),solution:[b(String.raw`Here $\sqrt T=3$, so $\eta=3/(2\cdot3)=0.5$.`,String.raw`Ở đây $\sqrt T=3$, nên $\eta=3/(2\cdot3)=0.5$.`),b(String.raw`The two terms are $D^2/(2\eta)=9$ and $\eta G^2T/2=0.5(4)(9)/2=9$.`,String.raw`Hai hạng là $D^2/(2\eta)=9$ và $\eta G^2T/2=0.5(4)(9)/2=9$.`),b(String.raw`Thus the bound is 18, matching $DG\sqrt T=3(2)(3)=18$.`,String.raw`Vậy cận bằng 18, đúng bằng $DG\sqrt T=3(2)(3)=18$.`)]},
      {prompt:b(String.raw`If $D=1$, $G=2$, and the horizon doubles from $T=25$ to $T=100$, compare the optimized bound and step size.`,String.raw`Nếu $D=1$, $G=2$ và chân trời tăng từ $T=25$ lên $T=100$, hãy so cận tối ưu và bước.`),solution:[b(String.raw`At $T=25$, $\eta=1/(2\cdot5)=0.1$ and the bound is 10.`,String.raw`Tại $T=25$, $\eta=1/(2\cdot5)=0.1$ và cận bằng 10.`),b(String.raw`At $T=100$, $\eta=1/(2\cdot10)=0.05$ and the bound is $1(2)(10)=20$.`,String.raw`Tại $T=100$, $\eta=1/(2\cdot10)=0.05$ và cận là $1(2)(10)=20$.`),b('The horizon doubling multiplies the bound by 2 because √T doubles, while the minimizing step is halved.','Chân trời tăng bốn lần làm cận tăng 2 vì √T tăng gấp đôi, còn bước tối ưu giảm một nửa.') ]},
    ],
    reviewNote:'Checked the balancing derivative, both equal terms at the optimum, and the fixed-comparator scope of the certificate.',sourceIds:['o-hazan'],
  },
  'm2-w089-e2': {
    title:b('Derive the projected-gradient distance inequality','Suy bất đẳng thức khoảng cách của gradient chiếu'),
    prompt:b(String.raw`For closed convex $K$ and $u\in K$, derive $|x_{t+1}-u|^2\le|x_t-u|^2-2\eta g_t^T(x_t-u)+\eta^2|g_t|^2$ from $x_{t+1}=\Pi_K(x_t-\eta g_t)$. State the projection property used.`,String.raw`Với $K$ đóng lồi, $u\in K$, hãy suy $|x_{t+1}-u|^2\le|x_t-u|^2-2\eta g_t^T(x_t-u)+\eta^2|g_t|^2$ từ $x_{t+1}=\Pi_K(x_t-\eta g_t)$. Nêu tính chất phép chiếu được dùng.`),
    application:b('Projection keeps every iterate feasible while controlling its distance to any feasible fixed comparator.','Phép chiếu giữ mọi iterate khả thi đồng thời khống chế khoảng cách tới comparator cố định khả thi bất kỳ.'),
    formula:b(String.raw`For Euclidean projection $p=\Pi_K(y)$ onto nonempty closed convex $K$, $|p-u|^2\le|y-u|^2$ for every $u\in K$. Set $y=x_t-\eta g_t$ and expand.`,String.raw`Với phép chiếu Euclidean $p=\Pi_K(y)$ lên $K$ đóng lồi không rỗng, $|p-u|^2\le|y-u|^2$ với mọi $u\in K$. Đặt $y=x_t-\eta g_t$ rồi khai triển.`),
    steps:[b('Set the unprojected point y equal to the gradient step.','Đặt điểm chưa chiếu y bằng bước gradient.'),b('Use that projection minimizes distance to y over K, comparing with the feasible point u.','Dùng việc phép chiếu cực tiểu khoảng cách tới y trên K, so với điểm khả thi u.'),b('Expand the squared norm and retain the cross term with its correct sign.','Khai triển bình phương chuẩn và giữ hạng tích chéo đúng dấu.')],
    primarySolution:[b(String.raw`Let $y=x_t-\eta g_t$. Since $u\in K$ and $x_{t+1}=\Pi_K(y)$, nearest-point optimality gives $|x_{t+1}-y|\le|u-y|$.`,String.raw`Đặt $y=x_t-\eta g_t$. Vì $u\in K$ và $x_{t+1}=\Pi_K(y)$, tính chất điểm gần nhất cho $|x_{t+1}-y|\le|u-y|$.`),b(String.raw`The projection variational inequality also gives $(y-x_{t+1})^T(u-x_{t+1})\le0$; expanding $|y-u|^2$ then yields $|x_{t+1}-u|^2\le|y-u|^2$.`,String.raw`Bất đẳng thức biến phân của phép chiếu còn cho $(y-x_{t+1})^T(u-x_{t+1})\le0$; khai triển $|y-u|^2$ suy ra $|x_{t+1}-u|^2\le|y-u|^2$.`),b(String.raw`Substitute $y=x_t-\eta g_t$: $|y-u|^2=|x_t-u|^2-2\eta g_t^T(x_t-u)+\eta^2|g_t|^2$.`,String.raw`Thế $y=x_t-\eta g_t$: $|y-u|^2=|x_t-u|^2-2\eta g_t^T(x_t-u)+\eta^2|g_t|^2$.`),b('Combining gives the required pathwise inequality. Closed convexity in Euclidean space ensures the projection exists and is unique.','Kết hợp cho bất đẳng thức theo từng đường đi cần chứng minh. Tính đóng lồi trong không gian Euclidean bảo đảm phép chiếu tồn tại và duy nhất.')],
    companions:[
      {prompt:b(String.raw`Project $y=(3,0)$ onto $K=\{(x_1,x_2):x_1^2+x_2^2\le1\}$. For comparator $u=(0,1)$, verify the squared-distance inequality numerically.`,String.raw`Chiếu $y=(3,0)$ lên $K=\{(x_1,x_2):x_1^2+x_2^2\le1\}$. Với comparator $u=(0,1)$, hãy kiểm tra số bất đẳng thức bình phương khoảng cách.`),solution:[b(String.raw`The nearest point in the unit disk is $p=(1,0)$.`,String.raw`Điểm gần nhất trong đĩa đơn vị là $p=(1,0)$.`),b(String.raw`The projected distance is $|p-u|^2=(1-0)^2+(0-1)^2=2$.`,String.raw`Khoảng cách sau chiếu là $|p-u|^2=(1-0)^2+(0-1)^2=2$.`),b(String.raw`The unprojected distance is $|y-u|^2=3^2+(-1)^2=10$, so $2\le10$ as required.`,String.raw`Khoảng cách chưa chiếu là $|y-u|^2=3^2+(-1)^2=10$, nên $2\le10$ như yêu cầu.`)]},
      {prompt:b(String.raw`Let $K=[0,\infty)$, $y=-2$, and comparator $u=3$. Find the projection and compare squared distances.`,String.raw`Cho $K=[0,\infty)$, $y=-2$ và comparator $u=3$. Tìm phép chiếu rồi so bình phương khoảng cách.`),solution:[b(String.raw`The closest feasible point to −2 is $\Pi_K(y)=0$.`,String.raw`Điểm khả thi gần −2 nhất là $\Pi_K(y)=0$.`),b(String.raw`The projected distance squared is $(0-3)^2=9$.`,String.raw`Bình phương khoảng cách sau chiếu là $(0-3)^2=9$.`),b(String.raw`The original distance squared is $(-2-3)^2=25$, hence $9\le25$.`,String.raw`Bình phương khoảng cách ban đầu là $(-2-3)^2=25$, do đó $9\le25$.`)]},
      {prompt:b(String.raw`In one dimension take $x_t=1$, $g_t=2$, $\eta=0.25$, $K=[0,1]$, and $u=0$. Compute the update and both sides of the projection inequality.`,String.raw`Trong một chiều, cho $x_t=1$, $g_t=2$, $\eta=0.25$, $K=[0,1]$, $u=0$. Tính bước cập nhật và hai vế bất đẳng thức chiếu.`),solution:[b(String.raw`The raw step is $x_t-\eta g_t=1-0.5=0.5$, already feasible, so $x_{t+1}=0.5$.`,String.raw`Bước thô là $x_t-\eta g_t=1-0.5=0.5$, đã khả thi nên $x_{t+1}=0.5$.`),b(String.raw`The left side is $|0.5-0|^2=0.25$.`,String.raw`Vế trái là $|0.5-0|^2=0.25$.`),b(String.raw`The right side is $1^2-2(0.25)(2)(1)+0.25^2(2^2)=1-1+0.25=0.25$, so equality holds here.`,String.raw`Vế phải là $1^2-2(0.25)(2)(1)+0.25^2(2^2)=1-1+0.25=0.25$, nên tại đây có đẳng thức.`)]},
    ],
    reviewNote:'Checked projection comparison against a feasible point, variational-inequality sign, cross-term expansion, and boundary projections.',sourceIds:['o-hazan'],
  },
  'm2-w089-e3': {
    title:b('Telescope the static-regret proof','Khử liên tiếp chứng minh static regret'),
    prompt:b(String.raw`Combine the one-step projection inequality with convexity $f_t(x_t)-f_t(u)\le g_t^T(x_t-u)$. Sum over $t=1,\ldots,T$, telescope and use diameter $D$ and $|g_t|\le G$ to prove $\operatorname{Reg}_T(u)\le D^2/(2\eta)+\eta G^2T/2$. Optimize $\eta$.`,String.raw`Kết hợp bất đẳng thức phép chiếu một bước với tính lồi $f_t(x_t)-f_t(u)\le g_t^T(x_t-u)$. Cộng $t=1,\ldots,T$, khử liên tiếp và dùng đường kính $D$, $|g_t|\le G$ để chứng minh $\operatorname{Reg}_T(u)\le D^2/(2\eta)+\eta G^2T/2$. Tối ưu $\eta$.`),
    application:b('The distance potential converts a sequence of projected gradient steps into a regret bound against one comparator fixed through the horizon.','Thế năng khoảng cách đổi chuỗi bước gradient chiếu thành cận regret so với một comparator cố định suốt chân trời.'),
    formula:b(String.raw`For fixed $u\in K$, $a_t=\|x_t-u\|^2$ yields per-round gap at most $(a_t-a_{t+1})/(2\eta)+\eta G^2/2$. Thus $\operatorname{Reg}_T(u)\le D^2/(2\eta)+\eta G^2T/2$, minimized at $\eta=D/(G\sqrt T)$.`,String.raw`Với $u\in K$ cố định, đặt $a_t=\|x_t-u\|^2$ cho khoảng cách mỗi vòng không quá $(a_t-a_{t+1})/(2\eta)+\eta G^2/2$. Vì vậy $\operatorname{Reg}_T(u)\le D^2/(2\eta)+\eta G^2T/2$, nhỏ nhất tại $\eta=D/(G\sqrt T)$.`),
    steps:[b('Rearrange the projected-distance inequality and apply convexity to upper-bound each loss gap.','Sắp xếp bất đẳng thức khoảng cách chiếu và áp tính lồi để chặn trên khoảng cách loss mỗi vòng.'),b('Sum over rounds; intermediate squared distances cancel.','Cộng qua các vòng; các bình phương khoảng cách trung gian triệt tiêu.'),b('Bound the initial potential by D², discard the final nonnegative potential, and use G; differentiate in η to optimize.','Chặn thế năng ban đầu bởi D², bỏ thế năng cuối không âm và dùng G; lấy đạo hàm theo η để tối ưu.')],
    primarySolution:[b(String.raw`The projection inequality rearranges to $g_t^T(x_t-u)\le(a_t-a_{t+1})/(2\eta)+\eta\|g_t\|^2/2$, where $a_t=\|x_t-u\|^2$. Convexity bounds $f_t(x_t)-f_t(u)$ by this inner product.`,String.raw`Sắp xếp bất đẳng thức phép chiếu được $g_t^T(x_t-u)\le(a_t-a_{t+1})/(2\eta)+\eta\|g_t\|^2/2$, với $a_t=\|x_t-u\|^2$. Tính lồi chặn $f_t(x_t)-f_t(u)$ bằng tích vô hướng này.`),b(String.raw`Summing from 1 to T leaves $(a_1-a_{T+1})/(2\eta)+\eta\sum_t\|g_t\|^2/2$; all intermediate potentials cancel.`,String.raw`Cộng từ 1 đến T còn $(a_1-a_{T+1})/(2\eta)+\eta\sum_t\|g_t\|^2/2$; mọi thế năng trung gian triệt tiêu.`),b(String.raw`Since both points lie in K, $a_1\le D^2$; also $a_{T+1}\ge0$ and $\sum_t\|g_t\|^2\le TG^2$. This gives the claimed two-term bound.`,String.raw`Vì hai điểm thuộc K, $a_1\le D^2$; đồng thời $a_{T+1}\ge0$ và $\sum_t\|g_t\|^2\le TG^2$. Suy ra cận hai hạng đã nêu.`),b(String.raw`Differentiating in $\eta>0$ gives $-D^2/(2\eta^2)+G^2T/2=0$, hence $\eta=D/(G\sqrt T)$ and regret at most $DG\sqrt T$.`,String.raw`Lấy đạo hàm theo $\eta>0$ cho $-D^2/(2\eta^2)+G^2T/2=0$, nên $\eta=D/(G\sqrt T)$ và regret không quá $DG\sqrt T$.`),b('The comparator u is fixed across time, even if it is selected in hindsight after the loss sequence; no changing-path guarantee follows from this proof.','Comparator u cố định theo thời gian dù có thể chọn sau khi xem chuỗi loss; chứng minh này không cho bảo đảm đường đi thay đổi.')],
    companions:[
      {prompt:b(String.raw`For $D=2$, $G=3$, $T=4$, evaluate the bound at $\eta=1/3$ and at the optimized step.`,String.raw`Với $D=2$, $G=3$, $T=4$, hãy tính cận tại $\eta=1/3$ và tại bước tối ưu.`),solution:[b(String.raw`At $\eta=1/3$, the distance term is $4/(2/3)=6$ and the gradient term is $(1/3)(9)(4)/2=6$, total 12.`,String.raw`Tại $\eta=1/3$, hạng khoảng cách là $4/(2/3)=6$ và hạng gradient là $(1/3)(9)(4)/2=6$, tổng 12.`),b(String.raw`The optimized step is $D/(G\sqrt T)=2/(3\cdot2)=1/3$.`,String.raw`Bước tối ưu là $D/(G\sqrt T)=2/(3\cdot2)=1/3$.`),b(String.raw`Thus the optimized certificate is also $DG\sqrt T=2(3)(2)=12$.`,String.raw`Vì vậy chứng nhận tối ưu cũng là $DG\sqrt T=2(3)(2)=12$.`)]},
      {prompt:b(String.raw`For $D=1$, $G=1$, and $T=9$, evaluate the regret certificate with $\eta=1/2$ and identify the comparator scope.`,String.raw`Với $D=1$, $G=1$, $T=9$, hãy tính chứng nhận regret khi $\eta=1/2$ và nêu phạm vi comparator.`),solution:[b(String.raw`The distance term is $1/(2(1/2))=1$.`,String.raw`Hạng khoảng cách là $1/(2(1/2))=1$.`),b(String.raw`The gradient term is $(1/2)(1)(9)/2=2.25$, so total regret is at most 3.25.`,String.raw`Hạng gradient là $(1/2)(1)(9)/2=2.25$, nên regret không quá 3.25.`),b('The result applies to any fixed feasible u, including the best fixed choice in hindsight, but not a sequence of different comparators.','Kết quả áp dụng cho u khả thi cố định bất kỳ, kể cả lựa chọn cố định tốt nhất sau này, nhưng không áp dụng cho dãy comparator đổi theo thời gian.') ]},
      {prompt:b(String.raw`If the learning rate is doubled from the optimized value, how do the two terms change for positive D, G, and T?`,String.raw`Nếu learning rate tăng gấp đôi so với giá trị tối ưu, hai hạng thay đổi thế nào khi D, G, T dương?`),solution:[b(String.raw`At the optimum both terms equal $DG\sqrt T/2$.`,String.raw`Tại optimum, hai hạng đều bằng $DG\sqrt T/2$.`),b('Doubling η halves the inverse-η distance term but doubles the η gradient term.','Tăng gấp đôi η làm hạng khoảng cách tỷ lệ nghịch giảm nửa, còn hạng gradient tỷ lệ η tăng gấp đôi.'),b(String.raw`The total becomes $DG\sqrt T/4+DG\sqrt T=1.25DG\sqrt T$, larger than the balanced minimum.`,String.raw`Tổng thành $DG\sqrt T/4+DG\sqrt T=1.25DG\sqrt T$, lớn hơn giá trị cân bằng nhỏ nhất.`) ]},
    ],
    reviewNote:'Checked the regret inner-product sign, cancellation of all intermediate distances, endpoint bounds, optimizer, and fixed-comparator quantifier.',sourceIds:['o-hazan'],
  },
  'm2-w089-e4': {
    title:b('Regret is benchmark-relative, not profit','Regret là tương đối theo benchmark, không phải lợi nhuận'),
    prompt:b('An algorithm has regret 4 versus the best fixed weight but negative net return after fees. State valid and invalid claims.','Một thuật toán có regret 4 so với weight cố định tốt nhất nhưng net return âm sau phí. Nêu kết luận đúng và sai.'),
    application:b('A small cumulative loss gap can coexist with a losing strategy when every benchmark and the strategy lose money after costs.','Khoảng cách loss tích lũy nhỏ vẫn có thể đi cùng chiến lược lỗ khi cả benchmark lẫn chiến lược đều âm sau phí.'),
    formula:b(String.raw`Static regret is $\sum_t\ell_t(w_t)-\min_{w\in K}\sum_t\ell_t(w)$. A bound $\operatorname{Reg}_T\le4$ controls only this specified cumulative benchmark gap.`,String.raw`Static regret là $\sum_t\ell_t(w_t)-\min_{w\in K}\sum_t\ell_t(w)$. Cận $\operatorname{Reg}_T\le4$ chỉ khống chế khoảng cách tích lũy tới benchmark đã nêu.`),
    steps:[b('State the exact comparator and loss convention to which regret refers.','Nêu comparator và quy ước loss chính xác mà regret so sánh.'),b('Translate the bound into a statement about cumulative loss relative to that fixed benchmark.','Diễn giải cận thành phát biểu về loss tích lũy so với benchmark cố định đó.'),b('Keep realized net return and statistical or economic claims separate; neither follows from low regret alone.','Tách net return thực tế và phát biểu thống kê/kinh tế; không điều nào suy ra chỉ từ regret thấp.')],
    primarySolution:[b(String.raw`The valid statement is that cumulative loss is at most 4 above the best fixed weight under the declared loss definition.`,String.raw`Phát biểu đúng là loss tích lũy không quá 4 so với weight cố định tốt nhất theo định nghĩa loss đã nêu.`),b('The supplied negative net return means the realized strategy lost money after fees.','Net return âm đã cho nghĩa là chiến lược thực tế lỗ sau phí.'),b('Low benchmark-relative regret does not establish positive profit, risk-adjusted value, or statistical significance.','Regret thấp tương đối benchmark không chứng minh lợi nhuận dương, giá trị điều chỉnh rủi ro hay ý nghĩa thống kê.'),b('A profitability claim additionally needs a deployment-consistent return model, costs, constraints, and uncertainty analysis.','Claim lợi nhuận còn cần mô hình return phù hợp triển khai, chi phí, ràng buộc và phân tích bất định.')],
    companions:[
      {prompt:b('A policy loses 12 units and the best fixed comparator loses 10.5 units. Compute regret and state whether the policy made money.','Một policy lỗ 12 đơn vị còn comparator cố định tốt nhất lỗ 10.5. Tính regret và nêu policy có lời không.'),solution:[b('Regret is policy loss minus comparator loss: $12-10.5=1.5$.','Regret là loss policy trừ loss comparator: $12-10.5=1.5$.'),b('The positive regret says the policy lost 1.5 more units than that benchmark.','Regret dương nói policy lỗ nhiều hơn benchmark đó 1.5 đơn vị.'),b('Both losses are positive, so this comparison does not show that the policy made money.','Cả hai loss đều dương nên phép so sánh không cho thấy policy có lời.') ]},
      {prompt:b('A strategy’s return is 2% before fees and 3% total fees, while its regret to a benchmark is bounded by 0.1 loss units. What can be concluded?','Return chiến lược là 2% trước phí và tổng phí 3%, trong khi regret so với benchmark bị chặn 0.1 đơn vị loss. Có thể kết luận gì?'),solution:[b('Net return after fees is $2\%-3\%=-1\%$.','Net return sau phí là $2\%-3\%=-1\%$.'),b('The regret bound compares cumulative specified losses to the benchmark; it does not reverse this negative net return.','Cận regret so sánh loss tích lũy được chỉ định với benchmark; nó không đổi net return âm này.'),b('Conclude benchmark-relative loss control under the model, not profitability; fee and return conventions must also be aligned.','Kết luận kiểm soát loss tương đối benchmark theo mô hình, không phải lợi nhuận; quy ước phí và return cũng phải khớp.') ]},
      {prompt:b('Two algorithms have regret bounds 2 and 5 against different comparator classes. Can the bounds alone rank their realized returns?','Hai thuật toán có cận regret 2 và 5 so với hai lớp comparator khác nhau. Chỉ các cận này có xếp hạng được return thực tế không?'),solution:[b('The benchmark classes differ, so the two regret quantities need not measure the same comparison.','Hai lớp benchmark khác nhau nên hai regret không nhất thiết đo cùng phép so sánh.'),b('Even on a common comparator, regret bounds give relative cumulative-loss control, not the absolute loss level.','Ngay cả với comparator chung, cận regret chỉ kiểm soát loss tích lũy tương đối, không cho mức loss tuyệt đối.'),b('A return ranking requires comparable net-return definitions and realized or statistically justified performance evidence.','Xếp hạng return cần định nghĩa net-return có thể so sánh và bằng chứng hiệu năng thực tế hoặc có biện minh thống kê.') ]},
    ],
    reviewNote:'Checked the regret sign and benchmark definition, and distinguished relative loss from absolute net return and inference.',sourceIds:['o-hazan'],
  },
  'm2-w089-e5': {
    title:b('Static regret does not guarantee tracking','Static regret không bảo đảm theo kịp'),
    prompt:b(String.raw`Let $K=\{-1,1\}$ and let losses alternate their preferred sign for even T. Compare a fixed action with the changing oracle.`,String.raw`Cho $K=\{-1,1\}$ và loss luân phiên sign được ưa thích với T chẵn. Hãy so action cố định với oracle thay đổi.`),
    application:b('A policy can have no regret against the best fixed action yet perform poorly relative to a comparator that switches with changing regimes.','Policy có thể không regret so với action cố định tốt nhất nhưng kém so với comparator đổi theo chế độ.'),
    formula:b(String.raw`For $\ell_t(x)=\mathbf1\{x\ne s_t\}$ with alternating $s_t\in\{-1,1\}$, every fixed $x$ loses $T/2$, while the per-round comparator $u_t=s_t$ loses 0.`,String.raw`Với $\ell_t(x)=\mathbf1\{x\ne s_t\}$, $s_t\in\{-1,1\}$ luân phiên, mọi $x$ cố định thua $T/2$ vòng, còn comparator từng vòng $u_t=s_t$ thua 0.`),
    steps:[b('Specify an alternating preferred sign and the loss incurred by choosing the other sign.','Chỉ rõ sign ưu tiên luân phiên và loss khi chọn sign còn lại.'),b('Count losses for either constant action over an even horizon.','Đếm loss của từng action hằng trên chân trời chẵn.'),b('Compare that sequence with a changing oracle and identify the comparator mismatch.','So dãy đó với oracle thay đổi và chỉ ra comparator khác nhau.')],
    primarySolution:[b(String.raw`Set $s_t=1$ on odd rounds and $s_t=-1$ on even rounds, with loss 0 for matching x and 1 otherwise.`,String.raw`Đặt $s_t=1$ ở vòng lẻ, $s_t=-1$ ở vòng chẵn, loss 0 nếu x khớp và 1 nếu không.`),b('A fixed action chooses one sign, so it is wrong on exactly half of the even T rounds and incurs loss T/2.','Action cố định chọn một sign nên sai đúng nửa trong T vòng chẵn và chịu loss T/2.'),b(String.raw`The changing comparator $u_t=s_t$ incurs zero loss each round. Thus the best-fixed baseline is not a tracking guarantee.`,String.raw`Comparator đổi $u_t=s_t$ chịu loss bằng không mỗi vòng. Vì vậy benchmark cố định tốt nhất không bảo đảm tracking.`)],
    companions:[
      {prompt:b(String.raw`For $T=12$ alternating binary preferred signs, compute the loss of each fixed action and of the switching oracle.`,String.raw`Với $T=12$ sign nhị phân ưa thích luân phiên, tính loss của action cố định và oracle đổi.`),solution:[b(String.raw`Each of the signs is preferred on six rounds.`,String.raw`Mỗi sign được ưa thích trong sáu vòng.`),b(String.raw`A fixed action is wrong on the other six rounds, so its loss is 6.`,String.raw`Action cố định sai ở sáu vòng còn lại nên loss bằng 6.`),b('The oracle switches to the preferred sign each round and has loss 0.','Oracle đổi sang sign ưu tiên mỗi vòng và có loss bằng 0.') ]},
      {prompt:b(String.raw`For alternating losses with $T=8$, what is static regret of either fixed action, and what is its dynamic-oracle gap?`,String.raw`Với loss luân phiên và $T=8$, static regret của mỗi action cố định là bao nhiêu, và khoảng cách tới dynamic oracle là gì?`),solution:[b(String.raw`Both constant actions lose on four of eight rounds, so the best fixed loss is 4.`,String.raw`Cả hai action hằng thua bốn trong tám vòng nên loss cố định tốt nhất là 4.`),b(String.raw`An action that always plays +1 also loses 4, giving static regret $4-4=0$.`,String.raw`Action luôn chơi +1 cũng thua 4 nên static regret là $4-4=0$.`),b(String.raw`The changing oracle loses 0, so the same fixed action has dynamic gap 4 despite zero static regret.`,String.raw`Oracle thay đổi thua 0 nên action cố định có khoảng cách động 4 dù static regret bằng không.`)]},
      {prompt:b(String.raw`If the preferred sign changes only once, why does a static-regret bound still fail to specify the cost of tracking? Name a needed comparator quantity.`,String.raw`Nếu sign ưa thích chỉ đổi một lần, vì sao cận static regret vẫn không xác định chi phí tracking? Hãy nêu đại lượng comparator cần có.`),solution:[b('Static regret compares with one constant sign and has no term measuring a switch in the comparator.','Static regret so với một sign hằng và không có hạng đo lần đổi comparator.'),b('A changing comparator can reduce loss on rounds after the regime change, so its gap is a different objective.','Comparator đổi có thể giảm loss ở các vòng sau khi đổi chế độ nên khoảng cách đó là mục tiêu khác.'),b(String.raw`A dynamic-regret analysis should specify path variation such as $P_T=\sum_{t=2}^T|u_t-u_{t-1}|$ and the assumptions connecting it to the bound.`,String.raw`Phân tích dynamic regret nên nêu path variation như $P_T=\sum_{t=2}^T|u_t-u_{t-1}|$ và các giả thiết nối nó với cận.`)]},
    ],
    reviewNote:'Checked the even-horizon loss count for both fixed signs and the zero-loss switching comparator; static and dynamic benchmarks remain distinct.',sourceIds:['o-hazan'],
  },
  'm2-w090-e1': {
    title:b('Compare logarithmic and generic regret numerically','So sánh số cận logarithmic và cận tổng quát'),
    prompt:b(String.raw`For $\mu=2$, $G=3$, $D=0.5$, and $T=10$, compute the strongly-convex logarithmic bound and the generic $DG\sqrt T$ bound. State which is numerically smaller at this horizon without claiming asymptotic dominance.`,String.raw`Với $\mu=2$, $G=3$, $D=0.5$, $T=10$, hãy tính cận logarithmic lồi mạnh và cận tổng quát $DG\sqrt T$. Nêu cận nào nhỏ hơn tại chân trời này mà không khẳng định ưu thế tiệm cận.`),
    application:b('A theorem with a better asymptotic rate can have a looser numerical certificate at a short finite horizon.','Định lý có tốc độ tiệm cận tốt hơn vẫn có thể cho chứng nhận số lỏng hơn ở chân trời hữu hạn ngắn.'),
    formula:b(String.raw`For the schedule-specific strongly-convex term use $G^2(1+\ln T)/(2\mu)$; a version with startup term adds $\mu D^2/2$. The generic convex bound is $DG\sqrt T$.`,String.raw`Với hạng lồi mạnh theo lịch bước dùng $G^2(1+\ln T)/(2\mu)$; phiên bản có hạng khởi động cộng $\mu D^2/2$. Cận lồi tổng quát là $DG\sqrt T$.`),
    steps:[b('Substitute the parameters in the logarithmic expression and use the natural logarithm.','Thế tham số vào biểu thức logarithmic và dùng logarithm tự nhiên.'),b('If reporting the optional diameter startup term, add it separately and label the convention.','Nếu báo hạng khởi động đường kính tùy chọn, cộng riêng và ghi rõ quy ước.'),b('Evaluate DG√T independently and compare the finite-horizon numbers without changing their asymptotic interpretation.','Tính riêng DG√T rồi so số hữu hạn mà không đổi cách hiểu tiệm cận.')],
    primarySolution:[b(String.raw`The logarithmic term is $(G^2/(2\mu))(1+\ln T)=(9/4)(1+\ln10)\approx7.4308$.`,String.raw`Hạng logarithmic là $(G^2/(2\mu))(1+\ln T)=(9/4)(1+\ln10)\approx7.4308$.`),b(String.raw`The optional startup term is $\mu D^2/2=2(0.5)^2/2=0.25$, so including it gives about 7.6808.`,String.raw`Hạng khởi động tùy chọn là $\mu D^2/2=2(0.5)^2/2=0.25$, nên nếu tính vào thì được khoảng 7.6808.`),b(String.raw`The generic bound is $DG\sqrt T=0.5(3)\sqrt{10}\approx4.7434$, smaller than either logarithmic number at this horizon.`,String.raw`Cận tổng quát là $DG\sqrt T=0.5(3)\sqrt{10}\approx4.7434$, nhỏ hơn cả hai số logarithmic tại chân trời này.`),b('This finite comparison does not contradict O(log T) versus O(√T) asymptotic rates; constants, startup terms, and horizon determine the displayed numbers.','So sánh hữu hạn này không mâu thuẫn tốc độ tiệm cận O(log T) và O(√T); hằng số, hạng khởi động và chân trời quyết định các số được báo.')],
    companions:[
      {prompt:b(String.raw`For $\mu=1$, $G=2$, $D=1$, $T=4$, compare $G^2(1+\ln T)/(2\mu)$ and $DG\sqrt T$.`,String.raw`Với $\mu=1$, $G=2$, $D=1$, $T=4$, hãy so $G^2(1+\ln T)/(2\mu)$ và $DG\sqrt T$.`),solution:[b(String.raw`The logarithmic term is $4(1+\ln4)/2=2(1+1.3863)\approx4.7726$.`,String.raw`Hạng logarithmic là $4(1+\ln4)/2=2(1+1.3863)\approx4.7726$.`),b(String.raw`The generic bound is $1(2)\sqrt4=4$.`,String.raw`Cận tổng quát là $1(2)\sqrt4=4$.`),b('The generic numerical bound is smaller at T=4; this says nothing about which rate eventually dominates.','Cận tổng quát nhỏ hơn tại T=4; điều này không nói tốc độ nào cuối cùng trội hơn.') ]},
      {prompt:b(String.raw`For $\mu=3$, $G=2$, $D=0.2$, $T=100$, calculate the logarithmic term with the optional startup term and the generic bound.`,String.raw`Với $\mu=3$, $G=2$, $D=0.2$, $T=100$, tính hạng logarithmic có cộng hạng khởi động tùy chọn và cận tổng quát.`),solution:[b(String.raw`The logarithmic part is $(4/6)(1+\ln100)\approx(2/3)(5.6052)=3.7368$.`,String.raw`Phần logarithmic là $(4/6)(1+\ln100)\approx(2/3)(5.6052)=3.7368$.`),b(String.raw`The startup term is $3(0.2)^2/2=0.06$, giving approximately 3.7968.`,String.raw`Hạng khởi động là $3(0.2)^2/2=0.06$, cho xấp xỉ 3.7968.`),b(String.raw`The generic bound is $0.2(2)\sqrt{100}=4$, so the logarithmic expression is now slightly smaller under this convention.`,String.raw`Cận tổng quát là $0.2(2)\sqrt{100}=4$, nên biểu thức logarithmic hiện nhỏ hơn một chút theo quy ước này.`)]},
      {prompt:b(String.raw`For $\mu=2$, $G=3$, $D=0.5$, compare the logarithmic and generic expressions at $T=10^6$ and explain the rate-level implication.`,String.raw`Với $\mu=2$, $G=3$, $D=0.5$, hãy so biểu thức logarithmic và tổng quát tại $T=10^6$, rồi giải thích hệ quả về tốc độ.`),solution:[b(String.raw`The logarithmic term is $(9/4)(1+\ln10^6)\approx(9/4)(14.8155)\approx33.3349$.`,String.raw`Hạng logarithmic là $(9/4)(1+\ln10^6)\approx(9/4)(14.8155)\approx33.3349$.`),b(String.raw`The generic bound is $0.5(3)\sqrt{10^6}=1500$.`,String.raw`Cận tổng quát là $0.5(3)\sqrt{10^6}=1500$.`),b('The logarithmic expression is much smaller here, illustrating asymptotic improvement under strong convexity; the theorem still requires its curvature and step-size assumptions.','Biểu thức logarithmic nhỏ hơn nhiều ở đây, minh họa cải thiện tiệm cận dưới lồi mạnh; định lý vẫn cần giả thiết curvature và bước học.') ]},
    ],
    reviewNote:'Checked natural-log values, optional startup-term convention, generic expression, and avoided extrapolating a short-horizon ordering.',sourceIds:['o-hazan'],
  },
  'm2-w090-e2': {
    title:b('Derive strongly-convex OGD’s one-step bound','Suy cận một bước của OGD lồi mạnh'),
    prompt:b(String.raw`Assume each $f_t$ is $\mu$-strongly convex, $|g_t|\le G$, projection is onto closed convex K, and $\eta_t=1/(\mu t)$. Combine strong convexity with the projection inequality and sum to prove $\operatorname{Reg}_T(u)\le(G^2/(2\mu))(1+\log T)$. Show that the distance terms cancel.`,String.raw`Giả sử mỗi $f_t$ lồi mạnh $\mu$, $|g_t|\le G$, phép chiếu lên K đóng lồi và $\eta_t=1/(\mu t)$. Kết hợp lồi mạnh với bất đẳng thức phép chiếu rồi cộng để chứng minh $\operatorname{Reg}_T(u)\le(G^2/(2\mu))(1+\log T)$. Hãy chỉ ra các hạng khoảng cách triệt tiêu.`),
    application:b('Curvature allows a decreasing learning-rate schedule to accumulate a logarithmic rather than square-root gradient penalty.','Độ cong cho phép lịch learning-rate giảm để tích lũy penalty gradient logarithmic thay vì căn bậc hai.'),
    formula:b(String.raw`For $a_t=\|x_t-u\|^2$ and $\eta_t=1/(\mu t)$, the one-step gap is at most $(\mu/2)[(t-1)a_t-ta_{t+1}]+G^2/(2\mu t)$.`,String.raw`Với $a_t=\|x_t-u\|^2$ và $\eta_t=1/(\mu t)$, khoảng cách loss mỗi bước không quá $(\mu/2)[(t-1)a_t-ta_{t+1}]+G^2/(2\mu t)$.`),
    steps:[b('Strong convexity subtracts a curvature term from the linearized loss gap.','Lồi mạnh trừ một hạng độ cong khỏi khoảng cách loss tuyến tính hóa.'),b('Use the projection inequality and substitute the time-varying ηt.','Dùng bất đẳng thức phép chiếu và thế ηt biến thiên theo thời gian.'),b('Sum the weighted distance differences and bound the harmonic sum by 1+log T.','Cộng các hiệu khoảng cách có trọng số và chặn tổng điều hòa bởi 1+log T.')],
    primarySolution:[b(String.raw`Strong convexity gives $f_t(x_t)-f_t(u)\le g_t^T(x_t-u)-(\mu/2)a_t$. Projection gives $g_t^T(x_t-u)\le(a_t-a_{t+1})/(2\eta_t)+\eta_tG^2/2$.`,String.raw`Lồi mạnh cho $f_t(x_t)-f_t(u)\le g_t^T(x_t-u)-(\mu/2)a_t$. Phép chiếu cho $g_t^T(x_t-u)\le(a_t-a_{t+1})/(2\eta_t)+\eta_tG^2/2$.`),b(String.raw`Set $\eta_t=1/(\mu t)$. Combining yields $(\mu/2)[(t-1)a_t-ta_{t+1}]+G^2/(2\mu t)$.`,String.raw`Thế $\eta_t=1/(\mu t)$. Kết hợp cho $(\mu/2)[(t-1)a_t-ta_{t+1}]+G^2/(2\mu t)$.`),b(String.raw`Summing t=1,…,T cancels all interior weighted distances and leaves $-(\mu T/2)a_{T+1}\le0$, so no positive diameter startup term is needed with this index\ing.`,String.raw`Cộng t=1,…,T triệt mọi khoảng cách có trọng số ở giữa và còn $-(\mu T/2)a_{T+1}\le0$, nên theo chỉ số này không cần hạng khởi động đường kính dương.`),b(String.raw`Finally, $\sum_{t=1}^T1/t=H_T\le1+\log T$, giving $\operatorname{Reg}_T(u)\le(G^2/(2\mu))(1+\log T)$.`,String.raw`Cuối cùng, $\sum_{t=1}^T1/t=H_T\le1+\log T$, nên $\operatorname{Reg}_T(u)\le(G^2/(2\mu))(1+\log T)$.`)],
    companions:[
      {prompt:b(String.raw`For $\mu=2$, $G=4$, and $T=3$, compute the one-step schedule and resulting harmonic regret bound.`,String.raw`Với $\mu=2$, $G=4$, $T=3$, hãy tính lịch từng bước và cận regret điều hòa.`),solution:[b(String.raw`The learning rates are $\eta_1=1/2$, $\eta_2=1/4$, and $\eta_3=1/6$.`,String.raw`Các learning-rate là $\eta_1=1/2$, $\eta_2=1/4$ và $\eta_3=1/6$.`),b(String.raw`The bound is $(16/4)(1+1/2+1/3)=4(11/6)=22/3$.`,String.raw`Cận là $(16/4)(1+1/2+1/3)=4(11/6)=22/3$.`),b('This uses the exact three-term harmonic number, which is no larger than 1+ln(3) only as an inequality direction check: 11/6≈1.8333≤2.0986.','Dùng tổng điều hòa chính xác ba hạng; kiểm tra chiều bất đẳng thức: 11/6≈1.8333≤1+ln(3)≈2.0986.') ]},
      {prompt:b(String.raw`For $\mu=1$, $G=2$, $T=4$, use the theorem’s $1+\log T$ bound and verify the distance telescoping endpoint sign.`,String.raw`Với $\mu=1$, $G=2$, $T=4$, hãy dùng cận $1+\log T$ của định lý và kiểm tra dấu hạng biên sau khi khử khoảng cách.`),solution:[b(String.raw`The gradient coefficient is $G^2/(2\mu)=4/2=2$, so the stated bound is $2(1+\ln4)\approx4.7726$.`,String.raw`Hệ số gradient là $G^2/(2\mu)=4/2=2$, nên cận là $2(1+\ln4)\approx4.7726$.`),b(String.raw`The weighted distance sum leaves $-(\mu T/2)a_{T+1}=-(1)(4)a_5/2=-2a_5$.`,String.raw`Tổng khoảng cách có trọng số còn $-(\mu T/2)a_{T+1}=-(1)(4)a_5/2=-2a_5$.`),b(String.raw`Since $a_5\ge0$, the endpoint is nonpositive and can be discarded in an upper bound.`,String.raw`Vì $a_5\ge0$, hạng biên không dương và có thể bỏ khi lấy cận trên.`)]},
      {prompt:b(String.raw`What rate follows at fixed $\mu,G$ as T grows, and which hypothesis in the one-step proof creates it?`,String.raw`Khi T tăng với $\mu,G$ cố định, suy ra tốc độ nào và giả thiết nào trong chứng minh một bước tạo ra tốc độ đó?`),solution:[b('The displayed regret grows at most proportionally to 1+log T.','Regret được hiển thị tăng không quá tỷ lệ với 1+log T.'),b('The curvature term from strong convexity cancels the increasing part of the distance potential under ηt=1/(μt).','Hạng độ cong từ lồi mạnh triệt phần tăng của thế năng khoảng cách khi ηt=1/(μt).'),b('Without a common positive μ and the stated update/projection assumptions, this derivation does not certify the logarithmic rate.','Thiếu μ dương chung và giả thiết cập nhật/phép chiếu đã nêu thì suy dẫn này không chứng nhận tốc độ logarithmic.') ]},
    ],
    reviewNote:'Checked the strong-convexity inequality, substitution of ηt, weighted-distance telescoping endpoint, and harmonic bound with μ>0.',sourceIds:['o-hazan'],
  },
  'm2-w090-e3': {
    title:b('Verify common curvature and gradient bounds','Kiểm tra độ cong chung và gradient bound'),
    prompt:b(String.raw`For $f_t(x)=a_tx^2/2+b_tx$ on $[-1,1]$, with $a_t\in[0.5,2]$ and $|b_t|\le B$, find a common strong-convexity parameter $\mu$ and a valid gradient bound G.`,String.raw`Với $f_t(x)=a_tx^2/2+b_tx$ trên $[-1,1]$, $a_t\in[0.5,2]$ và $|b_t|\le B$, hãy tìm tham số lồi mạnh chung $\mu$ và cận gradient hợp lệ G.`),
    application:b('A time-uniform curvature lower bound lets one choose one strongly-convex regret theorem for every round.','Cận dưới độ cong đồng nhất theo thời gian cho phép dùng cùng định lý regret lồi mạnh ở mọi vòng.'),
    formula:b(String.raw`For twice-differentiable $f_t$, $f_t''(x)=a_t\ge0.5$, so $\mu=0.5$ works. On $[-1,1]$, $|f_t'(x)|=|a_tx+b_t|\le2+B$, so $G=2+B$.`,String.raw`Với $f_t$ khả vi hai lần, $f_t''(x)=a_t\ge0.5$, nên $\mu=0.5$ hợp lệ. Trên $[-1,1]$, $|f_t'(x)|=|a_tx+b_t|\le2+B$, nên $G=2+B$.`),
    steps:[b('Differentiate twice and take the smallest curvature allowed over all t.','Lấy đạo hàm hai lần rồi lấy độ cong nhỏ nhất được phép qua mọi t.'),b('Differentiate once and bound both terms using |x|≤1, at≤2 and |bt|≤B.','Lấy đạo hàm một lần rồi chặn hai hạng bằng |x|≤1, at≤2 và |bt|≤B.'),b('State that the constants are uniform in t and valid on the given domain.','Nêu các hằng số đồng đều theo t và hợp lệ trên miền đã cho.')],
    primarySolution:[b(String.raw`The second derivative is $f_t''(x)=a_t$. Since $a_t\ge0.5$ for every t, each loss is 0.5-strongly convex on the interval.`,String.raw`Đạo hàm bậc hai là $f_t''(x)=a_t$. Vì $a_t\ge0.5$ với mọi t, mỗi loss lồi mạnh 0.5 trên đoạn.`),b(String.raw`The gradient is $f_t'(x)=a_tx+b_t$.`,String.raw`Gradient là $f_t'(x)=a_tx+b_t$.`),b(String.raw`For $|x|\le1$, $|a_tx+b_t|\le a_t|x|+|b_t|\le2+B$.`,String.raw`Với $|x|\le1$, $|a_tx+b_t|\le a_t|x|+|b_t|\le2+B$.`),b(String.raw`Thus one may use common constants $\mu=0.5$ and $G=2+B$. The range of b alone does not imply a bound smaller than this uniform one.`,String.raw`Vì vậy có thể dùng hằng số chung $\mu=0.5$ và $G=2+B$. Riêng miền của b không suy ra cận đều nhỏ hơn.`)],
    companions:[
      {prompt:b(String.raw`If $a_t\in[1,3]$ and $|b_t|\le2$ on $[-2,2]$, find valid common $\mu$ and G.`,String.raw`Nếu $a_t\in[1,3]$, $|b_t|\le2$ trên $[-2,2]$, hãy tìm $\mu$ chung và G hợp lệ.`),solution:[b(String.raw`The second derivative is $a_t\ge1$, so choose $\mu=1$.`,String.raw`Đạo hàm bậc hai là $a_t\ge1$, nên chọn $\mu=1$.`),b(String.raw`The first derivative is $a_tx+b_t$.`,String.raw`Đạo hàm bậc nhất là $a_tx+b_t$.`),b(String.raw`Using $a_t\le3$ and $|x|\le2$ gives $|f_t'(x)|\le3(2)+2=8$, so G=8 is valid.`,String.raw`Dùng $a_t\le3$, $|x|\le2$ được $|f_t'(x)|\le3(2)+2=8$, nên G=8 hợp lệ.`)]},
      {prompt:b(String.raw`For $f_t(x)=0.8x^2/2+5x$ on $[-1,1]$, verify the common μ and gradient bound using $a_t=0.8$, $b_t=5$.`,String.raw`Với $f_t(x)=0.8x^2/2+5x$ trên $[-1,1]$, hãy kiểm tra μ chung và cận gradient với $a_t=0.8$, $b_t=5$.`),solution:[b(String.raw`Its curvature is $f_t''=0.8$, so the example is at least 0.5-strongly convex.`,String.raw`Độ cong là $f_t''=0.8$, nên ví dụ lồi mạnh ít nhất 0.5.`),b(String.raw`The derivative is $0.8x+5$, whose absolute value on $[-1,1]$ is at most $0.8+5=5.8$.`,String.raw`Đạo hàm là $0.8x+5$, trị tuyệt đối trên $[-1,1]$ không quá $0.8+5=5.8$.`),b(String.raw`The uniform formula gives $G=2+B=7$ when B=5, a valid looser bound than the exact 5.8 for this single loss.`,String.raw`Công thức đều cho $G=2+B=7$ khi B=5, là cận hợp lệ lỏng hơn 5.8 chính xác của loss đơn này.`)]},
      {prompt:b(String.raw`If $a_t$ can equal zero on some rounds while $|b_t|\le B$, which part of the strongly-convex regret theorem is no longer certified?`,String.raw`Nếu $a_t$ có thể bằng không ở vài vòng trong khi $|b_t|\le B$, phần nào của định lý regret lồi mạnh không còn được chứng nhận?`),solution:[b('The gradient bound may still hold because it follows from the coefficient and domain bounds.','Cận gradient vẫn có thể đúng vì suy từ cận hệ số và miền.'),b('But no positive common curvature lower bound is available on those rounds.','Nhưng không có cận dưới độ cong chung dương ở các vòng đó.'),b('Thus the logarithmic strongly-convex guarantee cannot be invoked for the whole sequence without another positive-curvature premise or a different regret analysis.','Vì thế không thể áp bảo đảm logarithmic lồi mạnh cho toàn chuỗi nếu thiếu tiền đề độ cong dương khác hoặc phân tích regret khác.') ]},
    ],
    reviewNote:'Checked the minimum curvature across rounds, endpoint gradient maximum on the bounded domain, and dependence on a strictly positive common μ.',sourceIds:['o-hazan'],
  },
  'm2-w090-e4': {
    title:b('Linear losses do not justify logarithmic regret','Loss tuyến tính không biện minh regret logarithmic'),
    prompt:b(String.raw`For bounded linear adversarial losses on $[-1,1]$, can you claim logarithmic strongly-convex regret? Give a valid rate.`,String.raw`Với loss tuyến tính adversarial bị chặn trên $[-1,1]$, có thể khẳng định regret logarithmic lồi mạnh không? Hãy nêu tốc độ hợp lệ.`),
    application:b('An algorithmic theorem’s curvature premise must be checked against the actual per-round losses, not inferred from a bounded decision set.','Cần kiểm tra tiền đề độ cong của định lý thuật toán trên loss từng vòng thực tế, không suy từ miền quyết định bị chặn.'),
    formula:b(String.raw`A linear loss $f_t(x)=a_tx$ has $f_t''(x)=0$, so it is not strongly convex on a nontrivial interval. With $|a_t|\le G$ and diameter $D=2$, projected OGD gives the static bound $DG\sqrt T=2G\sqrt T$.`,String.raw`Loss tuyến tính $f_t(x)=a_tx$ có $f_t''(x)=0$, nên không lồi mạnh trên đoạn không tầm thường. Nếu $|a_t|\le G$, đường kính $D=2$, OGD chiếu cho cận tĩnh $DG\sqrt T=2G\sqrt T$.`),
    steps:[b('Differentiate the linear loss twice to test curvature directly.','Lấy đạo hàm loss tuyến tính hai lần để kiểm tra độ cong trực tiếp.'),b('Reject the strongly-convex logarithmic theorem because its positive-μ premise fails.','Bác áp dụng định lý logarithmic lồi mạnh vì tiền đề μ dương thất bại.'),b('Use the convex OGD bound with the interval diameter and an explicit gradient bound.','Dùng cận OGD lồi với đường kính đoạn và cận gradient tường minh.')],
    primarySolution:[b(String.raw`For $f_t(x)=a_tx$, the second derivative is zero, so no $\mu>0$ satisfies the strong-convexity inequality on all distinct points of $[-1,1]$.`,String.raw`Với $f_t(x)=a_tx$, đạo hàm bậc hai bằng không nên không có $\mu>0$ thỏa bất đẳng thức lồi mạnh trên mọi cặp điểm khác nhau trong $[-1,1]$.`),b('The bounded interval limits distance but does not create curvature in the loss.','Đoạn bị chặn giới hạn khoảng cách nhưng không tạo độ cong cho loss.'),b(String.raw`If $|a_t|\le G$, gradients are bounded by G and the set diameter is 2.`,String.raw`Nếu $|a_t|\le G$, gradient bị chặn bởi G và đường kính tập là 2.`),b(String.raw`The valid projected-OGD static guarantee is $2G\sqrt T$ using the convex bound; a logarithmic strongly-convex rate needs additional curvature.`,String.raw`Bảo đảm static OGD chiếu hợp lệ là $2G\sqrt T$ theo cận lồi; tốc độ logarithmic lồi mạnh cần thêm độ cong.`)],
    companions:[
      {prompt:b(String.raw`On $[-2,2]$, consider $f_t(x)=3x$ with $|f_t'(x)|=3$. State a valid OGD static-regret bound and why the strong-convex theorem is unavailable.`,String.raw`Trên $[-2,2]$, xét $f_t(x)=3x$ với $|f_t'(x)|=3$. Nêu cận static-regret OGD hợp lệ và vì sao không dùng được định lý lồi mạnh.`),solution:[b(String.raw`The interval diameter is $D=4$ and the gradient bound is $G=3$.`,String.raw`Đường kính đoạn là $D=4$ và cận gradient là $G=3$.`),b(String.raw`The convex bound gives $DG\sqrt T=12\sqrt T$.`,String.raw`Cận lồi cho $DG\sqrt T=12\sqrt T$.`),b('The loss has zero second derivative, so a positive strong-convexity parameter is not established.','Loss có đạo hàm bậc hai bằng không nên không có tham số lồi mạnh dương được chứng minh.') ]},
      {prompt:b(String.raw`For $f_t(x)=a_tx$ with $|a_t|\le1$ on $[-1,1]$, calculate the static OGD rate and distinguish it from a logarithmic claim.`,String.raw`Với $f_t(x)=a_tx$, $|a_t|\le1$ trên $[-1,1]$, hãy tính tốc độ static OGD và phân biệt với claim logarithmic.`),solution:[b(String.raw`Here $D=2$ and $G=1$.`,String.raw`Ở đây $D=2$ và $G=1$.`),b(String.raw`The generic convex bound is $2\sqrt T$.`,String.raw`Cận lồi tổng quát là $2\sqrt T$.`),b('This follows from bounded gradients and convexity; linearity supplies no positive curvature for a logarithmic strongly-convex rate.','Cận này dựa vào gradient bị chặn và tính lồi; tính tuyến tính không cho độ cong dương để có tốc độ logarithmic lồi mạnh.') ]},
      {prompt:b(String.raw`Add a quadratic term $\mu x^2/2$ to each linear loss on $[-1,1]$. What curvature does this provide, and what remains to check for a logarithmic regret bound?`,String.raw`Thêm hạng quadratic $\mu x^2/2$ vào từng loss tuyến tính trên $[-1,1]$. Hạng này cho độ cong nào và cần kiểm tra gì nữa để có cận regret logarithmic?`),solution:[b(String.raw`For $f_t(x)=a_tx+\mu x^2/2$, the second derivative is $\mu$, so μ>0 gives μ-strong convexity.`,String.raw`Với $f_t(x)=a_tx+\mu x^2/2$, đạo hàm bậc hai là $\mu$, nên μ>0 cho lồi mạnh μ.`),b('The gradient is $a_t+\mu x$, so on the interval it is bounded by $|a_t|+\mu$; a uniform bound is still needed.','Gradient là $a_t+\mu x$, nên trên đoạn bị chặn bởi $|a_t|+\mu$; vẫn cần cận đều.'),b('The theorem’s update, projection, common positive curvature, and initialization assumptions must also match; adding curvature alone does not prove every version.','Cũng cần khớp cập nhật, phép chiếu, độ cong dương chung và giả thiết khởi tạo của định lý; chỉ thêm độ cong chưa chứng minh mọi phiên bản.') ]},
    ],
    reviewNote:'Checked that boundedness of K is not curvature, used the interval diameter correctly, and stated the gradient premise for the convex OGD rate.',sourceIds:['o-hazan'],
  },
  'm2-w090-e5': {
    title:b('A linear function is not strongly convex on an interval','Hàm tuyến tính không lồi mạnh trên một đoạn'),
    prompt:b(String.raw`Prove that $f(x)=gx$ on a nontrivial interval cannot be $\mu$-strongly convex for any $\mu>0$.`,String.raw`Chứng minh $f(x)=gx$ trên đoạn không tầm thường không thể lồi mạnh $\mu$ với bất kỳ $\mu>0$.`),
    application:b('A claimed curvature-based rate must be supported by curvature in the objective itself; a straight-line loss has none.','Tốc độ dựa trên độ cong cần có độ cong trong chính objective; loss đường thẳng không có.'),
    formula:b(String.raw`Strong convexity requires $f(u)\ge f(x)+g(x)(u-x)+(\mu/2)|u-x|^2$ for every x,u. For linear f the first-order model is exact, contradicting the strictly positive final term when x≠u.`,String.raw`Lồi mạnh đòi $f(u)\ge f(x)+g(x)(u-x)+(\mu/2)|u-x|^2$ với mọi x,u. Với f tuyến tính, mô hình bậc nhất chính xác, mâu thuẫn với hạng cuối dương khi x≠u.`),
    steps:[b('Write the strong-convexity inequality for an arbitrary pair of distinct points.','Viết bất đẳng thức lồi mạnh cho một cặp điểm phân biệt bất kỳ.'),b('Substitute the exact linear increment and constant derivative.','Thế độ tăng tuyến tính chính xác và đạo hàm hằng.'),b('The remaining inequality would require a nonpositive quantity to dominate a positive quadratic term, which is impossible.','Bất đẳng thức còn lại đòi số không dương chặn trên hạng quadratic dương, điều không thể.')],
    primarySolution:[b(String.raw`Assume $\mu>0$ and choose distinct points x,u in the interval. Strong convexity requires $f(u)\ge f(x)+g(u-x)+(\mu/2)(u-x)^2$.`,String.raw`Giả sử $\mu>0$ và chọn x,u phân biệt trong đoạn. Lồi mạnh đòi $f(u)\ge f(x)+g(u-x)+(\mu/2)(u-x)^2$.`),b(String.raw`For $f(z)=gz$, the left side is $gu$ while $f(x)+g(u-x)=gx+g(u-x)=gu$.`,String.raw`Với $f(z)=gz$, vế trái là $gu$, còn $f(x)+g(u-x)=gx+g(u-x)=gu$.`),b(String.raw`The inequality reduces to $gu\ge gu+(\mu/2)(u-x)^2$, or $0\ge(\mu/2)(u-x)^2$.`,String.raw`Bất đẳng thức rút thành $gu\ge gu+(\mu/2)(u-x)^2$, hay $0\ge(\mu/2)(u-x)^2$.`),b('Because μ>0 and u≠x, the right side is positive, a contradiction. Thus no positive strong-convexity parameter exists on a nontrivial interval.','Vì μ>0 và u≠x, vế phải dương nên mâu thuẫn. Do đó không có tham số lồi mạnh dương trên đoạn không tầm thường.')],
    companions:[
      {prompt:b(String.raw`Test whether $f(x)=3x+1$ can be μ-strongly convex on $[-1,1]$ for μ>0 using two distinct points.`,String.raw`Dùng hai điểm phân biệt để kiểm tra $f(x)=3x+1$ có thể lồi mạnh μ trên $[-1,1]$ khi μ>0 không.`),solution:[b(String.raw`Choose x=−1 and u=1; the linear function has derivative 3.`,String.raw`Chọn x=−1, u=1; hàm tuyến tính có đạo hàm 3.`),b(String.raw`The exact tangent prediction is $f(-1)+3(1-(-1))=-2+6=4=f(1)$.`,String.raw`Dự báo tiếp tuyến chính xác là $f(-1)+3(1-(-1))=-2+6=4=f(1)$.`),b(String.raw`Strong convexity would require $4\ge4+2\mu$, impossible for μ>0.`,String.raw`Lồi mạnh sẽ đòi $4\ge4+2\mu$, điều không thể khi μ>0.`)]},
      {prompt:b(String.raw`On $[0,2]$, apply the μ-strong-convexity inequality to $f(x)=-2x$ at x=0,u=2 and derive the contradiction.`,String.raw`Trên $[0,2]$, áp bất đẳng thức lồi mạnh cho $f(x)=-2x$ tại x=0,u=2 và suy mâu thuẫn.`),solution:[b(String.raw`Here $f(0)=0$, $f(2)=-4$, and the derivative is −2.`,String.raw`Ở đây $f(0)=0$, $f(2)=-4$ và đạo hàm là −2.`),b(String.raw`The first-order term at x=0 predicts $f(0)+(-2)(2)=-4$, exactly the actual value.`,String.raw`Hạng bậc nhất tại x=0 dự đoán $f(0)+(-2)(2)=-4$, đúng bằng giá trị thực.`),b(String.raw`Strong convexity would demand $-4\ge-4+2\mu$, which fails for every μ>0.`,String.raw`Lồi mạnh sẽ đòi $-4\ge-4+2\mu$, sai với mọi μ>0.`)]},
      {prompt:b(String.raw`Why does the impossibility argument fail on a singleton domain, and why does that not certify a useful positive curvature rate?`,String.raw`Vì sao lập luận bất khả thi không áp dụng trên miền singleton, và vì sao điều đó không chứng nhận tốc độ dựa trên độ cong dương hữu ích?`),solution:[b('A singleton contains no pair x≠u, so the strong-convexity inequality has no distinct-point test.','Singleton không có cặp x≠u nên bất đẳng thức lồi mạnh không có phép thử điểm phân biệt.'),b('Under the pairwise definition, the condition can be vacuous for every μ on that domain.','Theo định nghĩa từng cặp, điều kiện có thể đúng rỗng với mọi μ trên miền đó.'),b('A learning-rate theorem still needs a nontrivial domain geometry and its other hypotheses; a vacuous curvature label does not establish meaningful regret improvement.','Định lý learning-rate vẫn cần hình học miền không tầm thường và giả thiết khác; nhãn độ cong đúng rỗng không chứng minh cải thiện regret có ý nghĩa.') ]},
    ],
    reviewNote:'Checked the strong-convexity definition at distinct points, exact tangency of linear functions, and the singleton-domain boundary.',sourceIds:['o-hazan'],
  },
};

